import { safeLocalStorage } from "../kit/platform";
import { setSpeechGate } from "../kit/speech";
import { mmToU, uToM } from "../sim/fixed";
import { applyCommand, createWorld, hashWorldHex, runLog, step, type World } from "../sim/world";
import { newWordsOf } from "../typing/deck";
import { createHud, type Hud } from "../ui/hud";
import { createLearningFrame, createPrelearn, createReviewCard, type LearningFramePresenter, type LearningPanel, type PanelWord } from "../ui/learning-frame";
import { createPlacementUi, type PlacementUi } from "../ui/placement-ui";
import { VICTORY_HOLD_MS, createResults } from "../ui/results";
import { createShopStrip } from "../ui/shop-strip";
import { createDebutCard } from "../ui/debut-card";
import { el, installSkin, keyLabel, setShown, uiButton } from "../ui/skin";
import { createTags } from "../ui/tags";
import { createWaveCard } from "../ui/wave-card";
import { createActors, type ActorsView } from "../view/actors";
import { createBanners, type BannersView } from "../view/banners";
import { foeDrawnSize } from "../view/foe-look";
import { createFx, type FxPresenter } from "../view/fx";
import { createHeroes } from "../view/heroes";
import { createHpBars } from "../view/hpbars";
import { createMapStage, type MapStage } from "../view/stage";
import { loadCrowdModels } from "../view/models";
import { createLaneCue } from "../view/lane-cue";
import { createTelegraphs, type TelegraphsView } from "../view/telegraphs";
import type { ActionHandler, FrameInfo, Presenter, Quality, ScreenPoint } from "./contracts";
import { createInputRouter, type InputRouter, type KeyPanel } from "./input-router";
import { createLearningClient, type LearningClient } from "./learning";
import { createLoop, type Loop } from "./loop";
import { createPaceCard } from "./pace-card";
import { PaceMeter, clampWpm, measuredHeader, offerEasy, paceLabel, paceOptions, readPaceMemory, recordStage, rememberPick, sameSpeed, type PaceHeader } from "./typing-pace";

export interface App {
  dispose(): void;
}

export interface AppOptions {
  readonly stage?: StageDef;
  readonly quality?: Quality;
  readonly seed?: number;
  readonly difficulty?: Difficulty;
  /** Typist speed E for word lengths and the pace k (01 §3.4, BALANCE.md §4.1); unset: the speed card asks. */
  readonly typistWpm?: number;
  /** Dev only: world time × speed (rules unchanged, scenarios run a whole stage faster). */
  readonly speed?: number;
  /** Show Học trước before the first setup (default true). */
  readonly prelearn?: boolean;
  /** Word tag size, 80–150 % (01 §3.1; the settings screen comes later). */
  readonly tagSizePct?: number;
}

const QUALITIES: readonly Quality[] = ["low", "medium", "high", "ultra"];
const DIFFICULTIES: readonly Difficulty[] = ["easy", "normal", "hard"];
/** One level easier (00 §4.10), and the levels' names (00 §4.10 table). */
const EASIER: Readonly<Record<Difficulty, Difficulty | null>> = { hard: "normal", normal: "easy", easy: null };
const DIFFICULTY_VI: Readonly<Record<Difficulty, string>> = { easy: "Easy", normal: "Normal", hard: "Hard" };
/** Countdown after a pause in a wave (06 §2 rule 4). */
const COUNTDOWN_MS = 3000;
/** How often the UI rectangles damage numbers keep off are read (fx.numbers.protected). */
const PROTECT_EVERY_MS = 250;
/** Foe pick radius for a left click, CSS px (00 §6 mouse). */
const PICK_PX = 44;
/** Word zone (01 §2.1, rules RINGS), sim u: fast-forward stays off while a foe is inside it. */
const WORD_ZONE_U = mmToU(RINGS.wordZoneMm);

/** URL options: ?q= quality, ?seed=, ?difficulty=, ?wpm=, ?prelearn=0, ?tagsize=80–150, and in dev ?speed=. */
export function optionsFromUrl(search: string, dev: boolean): AppOptions {
  const params = new URLSearchParams(search);
  const q = params.get("q") as Quality | null;
  const d = params.get("difficulty") as Difficulty | null;
  const num = (name: string): number | undefined => {
    const raw = params.get(name);
    const value = raw === null ? NaN : Number(raw);
    return Number.isFinite(value) ? value : undefined;
  };
  const speed = num("speed");
  return {
    quality: q && QUALITIES.includes(q) ? q : undefined,
    difficulty: d && DIFFICULTIES.includes(d) ? d : undefined,
    seed: num("seed"),
    // A whole WPM in 10–120: the world keeps integers only.
    typistWpm: clampWpm(num("wpm")),
    speed: dev && speed !== undefined ? Math.min(16, Math.max(0.25, speed)) : undefined,
    prelearn: params.get("prelearn") !== "0",
    tagSizePct: num("tagsize"),
  };
}

/** What a run owns; rebuilt on retry. */
interface Run {
  world: World;
  /** The typing speed the world was built with (replays use it too). */
  header: PaceHeader;
  /** Word timings of this run, folded into the measured profile when it ends. */
  meter: PaceMeter;
  log: { tick: number; command: SimCommand }[];
  presenters: Presenter[];
  /** Its 3D views (actors, telegraphs, bars, effects) and the roots they hung on the stage layers. */
  scene: { presenters: Presenter[]; roots: Object3D[] };
  handlers: ActionHandler[];
  actors: ActorsView;
  fx: FxPresenter;
  telegraphs: TelegraphsView;
  banners: BannersView;
  hud: Hud;
  placement: PlacementUi;
  /** The learning frame: covered while a learning panel asks (its lines would give answers away). */
  frame: LearningFramePresenter;
  prelearn: LearningPanel & { show(words: readonly PanelWord[]): void };
  review: LearningPanel & { show(items: Parameters<ReturnType<typeof createReviewCard>["show"]>[0]): void };
}

interface FrameStats {
  frames: number;
  /** Last 600 frame times, ms. */
  readonly times: number[];
  keyLatency: number[];
}

declare global {
  interface Window {
    /** Dev and scenario handle (dev builds, or ?debug=1). */
    __dh?: DebugHandle;
  }
}

export interface DebugHandle {
  readonly ready: boolean;
  world(): World;
  state(): Record<string, unknown>;
  words(): { slot: number; text: string; kind: string; typed: number; target: { slot: number; serial: number } | null; sx: number; sy: number; visible: boolean }[];
  foes(): { slot: number; serial: number; foe: string; hp: number; hpMax: number; word: number; x: number; z: number; sx: number; sy: number; visible: boolean }[];
  hash(): string;
  /** Replays the command log on a fresh world to the current tick; true when the hashes match. */
  replayCheck(): { live: string; replay: string; same: boolean; commands: number };
  perf(): { frames: number; meanMs: number; p95Ms: number; maxMs: number; drawCalls: number; triangles: number; keyLatencyMaxMs: number; keyLatencyMeanMs: number; keys: number };
  numbersOverlaps(): number;
  /** Pairs of live damage numbers whose drawn boxes touch (kit feedback/numbers.ts box(); must stay 0 after a frame). */
  numbersTouching(): number;
  /** The number field and the sprites that drew it last frame (dh-numbers-drawn reads the drawn quads and the atlas). */
  numberLayer(): Pick<FxPresenter, "numbers" | "sprites"> | null;
  setSpeed(speed: number): void;
  send(command: SimCommand): void;
  action(name: string): boolean;
  restart(): void;
  panel(): string | null;
  /** Answers of the open Thẻ Ôn, in order. */
  review(): string[];
  /** Events seen by type, the shortest enemy telegraph (ms), frames slowed by hit-stop, live telegraph shapes. */
  events(): { tally: Record<string, number>; telegraphMinMs: number | null; byFoe: Record<string, { n: number; minMs: number; shape: string }>; slowFrames: number; telegraphsLive: number };
  /** Drawn screen height (px) of every live foe, base to top anchor, with its distance to the dais (dh-scale, 05 §2.3). */
  foeSizes(): { foe: string; px: number; widthPx: number; distM: number }[];
  /** Presentation only: `count` tier 4–5 hits on live foes go to the effects (hit-stop, shake, numbers); the sim never sees them. */
  fxStorm(count: number): number;
  setView(view: { yawDeg?: number; pitchDeg?: number; zoom?: number; targetX?: number; targetZ?: number }, snap?: boolean): void;
  project(x: number, y: number, z: number): ScreenPoint;
}

export function startApp(doc: Document = document, given?: AppOptions): App {
  const view = doc.defaultView!;
  const dev = import.meta.env.DEV;
  const options: AppOptions = given ?? optionsFromUrl(view.location.search, dev);
  const stage = options.stage ?? STAGE_M0;
  const quality: Quality = options.quality ?? "high";
  const seed = options.seed ?? stage.seed;
  /** The typing speed of the next run: from ?wpm=, else unset until the speed card is answered. */
  const urlWpm = clampWpm(options.typistWpm);
  let header: PaceHeader | null = urlWpm === undefined ? null : { typistWpm: urlWpm, source: "url" };
  /** The stage's level (00 §4.10): from ?difficulty=, one lower after two defeats in a row when the player takes the offer. */
  let difficulty: Difficulty = options.difficulty ?? "normal";
  /** Defeats in a row on this stage (00 §4.10: two → offer one level easier). */
  let lossStreak = 0;
  let speed = options.speed ?? 1;

  installSkin(doc);
  const overlay = doc.getElementById("dh-overlay");
  const canvasHost = doc.getElementById("dh-canvas");
  if (!overlay || !canvasHost) throw new Error("app: #dh-overlay or #dh-canvas missing from index.html");
  overlay.replaceChildren();

  const notice = el(doc, "div", "dh-boot", "Dragonhold · " + stage.nameVi + " · loading words…");
  overlay.append(notice);

  const foundMap = MAPS[stage.mapId];
  if (!foundMap) throw new Error("app: stage " + stage.id + " names unknown map " + stage.mapId);
  const mapDef: MapDef = foundMap;
  const map: MapStage = createMapStage(canvasHost, mapDef, quality);
  map.render();

  // The Dragons live as long as the app: a retry resets them instead of loading and decoding the GLBs again.
  const heroes = createHeroes(map.stage, mapDef, { terrain: map.terrain });
  // The owner's M0b models (foes, the warden, traps, the hut, scatter props, the bridge): loaded once, every run's crowd takes them.
  const models = loadCrowdModels(quality);
  map.useModels(models);

  // Persistent services: audio, the learning bridge and client.
  const bridge = createPortalBridge();
  const learning: LearningClient = createLearningClient({ bridge });
  const audio: GameAudio = createAudio({ quality });
  const stopMusicWatch = bridge.onSharedMusic((playing) => audio.setSharedMusic(playing));
  setSpeechGate(async (play) => {
    for (let waited = 0; audio.speechBlocked() && waited < 1500; waited += 100) await new Promise((done) => view.setTimeout(done, 100));
    await play();
  });
  // 06 §2 rule 1: take the keys at load and ask the portal for focus.
  view.focus();
  bridge.requestFocus();

  // App-level layers.
  const hurt = el(doc, "div", "dh-hurt");
  /** Héo lan's seep: a violet edge each beat, stronger when a beat takes ≥ 5 % of max HP (test pass 27/10). */
  const seep = el(doc, "div", "dh-seep");
  /** Low HP (< 35 %): a slow red pulse at the edge (test pass 27/10). */
  const lowEdge = el(doc, "div", "dh-lowhp");
  /** A notice over the learning frame, where the eyes are: a Vietnamese IME, low HP with a potion in the bag. */
  const notice2 = el(doc, "div", "dh-notice");
  notice2.setAttribute("role", "status");
  setShown(notice2, false);
  const ffBadge = el(doc, "div", "dh-ff", "×2");
  setShown(ffBadge, false);
  /** Pause menu and 3-2-1: a plain dim layer, words and the learning frame hidden (01 §3.9 "Tạm dừng che chữ"). */
  const hush = el(doc, "div", "dh-hush");
  setShown(hush, false);
  const veil = el(doc, "div", "dh-veil");
  const veilText = el(doc, "div", "dh-veil__text", "");
  veil.append(veilText);
  setShown(veil, false);
  const countdownNode = el(doc, "div", "dh-countdown", "");
  setShown(countdownNode, false);
  const paceCard = createPaceCard(overlay);
  const menu = el(doc, "section", "dh-panel dh-pausemenu");
  menu.dataset.dhAvoid = "";
  menu.setAttribute("role", "dialog");
  menu.setAttribute("aria-label", "Paused");
  const menuItems: HTMLButtonElement[] = [];
  const menuTitle = el(doc, "div", "dh-pausemenu__title", "Paused");
  const menuKeys = el(doc, "div", "dh-pausemenu__keys", "↑ ↓ select · Enter confirm · Esc resume");
  setShown(menu, false);
  overlay.append(hurt, seep, lowEdge, notice2, ffBadge);

  let run: Run | null = null;
  let deck: WordDeck | null = null;
  let loop: Loop | null = null;
  let router: InputRouter | null = null;
  let disposed = false;
  let menuOpen = false;
  let menuIndex = 0;
  /** Focus pause (06 §2 rule 3): "focus" shows the veil; "soft" is the first-load hint. */
  let veilMode: "none" | "focus" | "soft" = "none";
  let countdownUntil = 0;
  let fastForward = false;
  let hurtUntil = 0;
  let seepUntil = 0;
  let seepStrong = false;
  /** The IME notice stays until a letter reaches the game (or 8 s). */
  let imeUntil = 0;
  /** A won stage turns the camera slowly while the results wait (results.ts VICTORY_HOLD_MS). */
  let victoryTurn: { yawDeg: number; zoom: number; at: number } | null = null;
  /** A tag appeared: read the keep-out rectangles again next frame, not 250 ms later (numbers under a fresh tag). */
  let keepOutSoon = false;
  let protectAt = 0;
  let audioPaused = false;
  let prelearnShown = false;
  /** The last Thẻ Ôn answers (debug handle: scenarios answer by keyboard). */
  let lastReview: string[] = [];
  const pendingKeyTimes: number[] = [];
  const stats: FrameStats = { frames: 0, times: [], keyLatency: [] };
  /** Events seen this run by type, and the shortest enemy telegraph (debug handle). */
  const tally: Record<string, number> = {};
  let telegraphMinMs = Infinity;
  /** Enemy telegraphs by species: count and shortest wind-up (dh-telegraphs). */
  const telegraphByFoe: Record<string, { n: number; minMs: number; shape: string }> = {};
  let slowFrames = 0;
  let lastFrameAt = 0;
  let keysToSim = 0;
  let keysToPanels = 0;

  /** The open learning panel, wrapped to count the letters it takes. */
  const activePanel = (): KeyPanel | null => {
    if (!run) return null;
    const panel = run.prelearn.isOpen ? run.prelearn : run.review.isOpen ? run.review : null;
    if (!panel) return null;
    return {
      isOpen: true,
      handleLetter: (letter) => {
        keysToPanels += 1;
        return panel.handleLetter(letter);
      },
      handleAction: (action) => panel.handleAction(action),
      // ⇧↵ in a break closes Thẻ Ôn and calls the next wave (its answers are not required).
      passOn: (action) => {
        if (action !== "call-early" || panel !== run?.review || run.world.phase !== "break") return false;
        panel.handleAction("escape");
        return true;
      },
    };
  };

  // ── Commands: straight into the world, logged with their tick ──
  /** `at`: when the key was pressed (the router's last letter, or now for a command sent by the debug handle). */
  const sinkAt = (command: SimCommand, at?: number): void => {
    if (!run) return;
    const world = run.world;
    if (world.phase === "victory" || world.phase === "defeat") return;
    applyCommand(world, command);
    run.log.push({ tick: world.tick, command });
    if (command.type === "key") {
      keysToSim += 1;
      imeUntil = 0;
      pendingKeyTimes.push(at ?? router?.stats.lastLetterAt ?? view.performance.now());
    }
  };
  const sink = (command: SimCommand): void => sinkAt(command);

  // ── Pause menu ──
  const menuActions: { label: string; run(): void }[] = [
    { label: "Resume", run: () => closeMenu() },
    { label: "Replay", run: () => { closeMenu(); restart(); } },
    { label: "Typing speed", run: () => openPaceFromMenu() },
  ];
  for (const [index, item] of menuActions.entries()) {
    const button = uiButton(doc, "dh-pausemenu__item", () => item.run());
    button.textContent = item.label;
    button.addEventListener("pointerenter", () => selectMenu(index));
    menuItems.push(button);
  }
  /** The menu row that names the speed in use. */
  const paceItem = menuItems[2]!;
  menu.append(menuTitle, ...menuItems, menuKeys);
  overlay.append(hush, menu, veil, countdownNode);

  function selectMenu(index: number): void {
    menuIndex = (index + menuItems.length) % menuItems.length;
    menuItems.forEach((button, k) => button.classList.toggle("is-on", k === menuIndex));
  }
  function openMenu(): void {
    if (!run || menuOpen || paceCard.isOpen) return;
    const phase = run.world.phase;
    if (phase === "victory" || phase === "defeat") return;
    menuOpen = true;
    paceItem.textContent = "Typing speed: " + paceLabel(run.header);
    selectMenu(0);
    setShown(menu, true);
    loop?.setPaused(true);
  }

  // ── Typing speed (typing-pace.ts) ──
  /**
   * Shows the speed card; `back`: Esc returns to the game (from the menu).
   * From the menu the speed in use is preselected (its own row when no
   * preset has it), so Enter on the card goes back to the game.
   */
  function askPace(onPick: (picked: PaceHeader, choice?: { easy: boolean }) => void, back?: () => void): void {
    const current = back ? run?.header : undefined;
    const { options: rows, selected } = paceOptions(readPaceMemory(safeLocalStorage), current);
    const note = current ? "A new speed restarts the stage." : undefined;
    paceCard.open(rows, selected, (picked, choice) => {
      // Keeping the speed in use keeps its source: a ?wpm= stays the portal's.
      if (!(current && sameSpeed(picked, current))) rememberPick(safeLocalStorage, picked);
      onPick(picked, choice);
    }, back, run?.header, note, back ? undefined : (wpm) => offerEasy(wpm, difficulty, false));
  }
  /**
   * Pause menu → speed card: another WPM replays the stage with it; the same
   * WPM, from any row or source, goes back to the game (test pass 27/10: a
   * ?wpm=35 game replayed the stage on Enter at the 35 row).
   */
  function openPaceFromMenu(): void {
    if (!run) return;
    menuOpen = false;
    setShown(menu, false);
    const current = run.header;
    askPace(
      (picked) => {
        if (sameSpeed(picked, current)) {
          startCountdownIfWave();
          return;
        }
        header = picked;
        restart();
        run?.hud.toast("Replay at " + paceLabel(picked));
      },
      () => startCountdownIfWave(),
    );
  }
  function closeMenu(): void {
    if (!menuOpen) return;
    menuOpen = false;
    setShown(menu, false);
    startCountdownIfWave();
  }
  function startCountdownIfWave(): void {
    const phase = run?.world.phase;
    if (phase === "wave" || phase === "warning") countdownUntil = view.performance.now() + COUNTDOWN_MS;
  }

  // ── Focus (06 §2) ──
  const inPlay = (): boolean => {
    const phase = run?.world.phase;
    return phase === "wave" || phase === "warning" || phase === "break";
  };
  const onBlur = (): void => {
    if (!run) return;
    if (inPlay()) {
      veilMode = "focus";
      veilText.textContent = "Click or press any key to resume";
      veil.classList.remove("is-soft");
      setShown(veil, true);
      countdownUntil = 0;
      loop?.setPaused(true); // now, not at the next frame: no tick slips in
    }
  };
  const onVisibility = (): void => {
    if (doc.visibilityState === "hidden") onBlur();
  };
  /** A press while the veil is up: lifts it; in a wave a 3-2-1 follows and the press is used up. */
  const liftVeil = (): boolean => {
    if (veilMode === "none") return false;
    const mode = veilMode;
    veilMode = "none";
    setShown(veil, false);
    if (mode === "soft") return false;
    const phase = run?.world.phase;
    if (phase === "wave" || phase === "warning") {
      countdownUntil = view.performance.now() + COUNTDOWN_MS;
      return true;
    }
    return false;
  };
  const onPointerDown = (): void => {
    view.focus();
    liftVeil();
  };
  view.addEventListener("blur", onBlur);
  doc.addEventListener("visibilitychange", onVisibility);
  view.addEventListener("pointerdown", onPointerDown, { capture: true });

  // ── Left click on a foe marks it (00 §6 mouse) ──
  const pickAt = { x: 0, y: 0, down: false };
  const onCanvasDown = (event: PointerEvent): void => {
    if (event.button !== 0) return;
    pickAt.x = event.clientX;
    pickAt.y = event.clientY;
    pickAt.down = true;
  };
  const onCanvasUp = (event: PointerEvent): void => {
    if (event.button !== 0 || !pickAt.down || !run) return;
    pickAt.down = false;
    if (Math.hypot(event.clientX - pickAt.x, event.clientY - pickAt.y) > 6 || run.placement.mode !== "idle") return;
    const rect = canvasHost.getBoundingClientRect();
    const px = event.clientX - rect.left;
    const py = event.clientY - rect.top;
    let best: { slot: number; serial: number } | null = null;
    let bestD = PICK_PX * PICK_PX;
    const point = new Vector3();
    const screen: ScreenPoint = { x: 0, y: 0, visible: false };
    for (const enemy of run.world.enemies.list) {
      if (!enemy.alive) continue;
      const located = run.actors.locate(enemy.slot, enemy.serial, "center", point);
      const x = located ? point.x : uToM(enemy.x);
      const y = located ? point.y : uToM(enemy.y) + 0.8;
      const z = located ? point.z : uToM(enemy.z);
      map.worldToScreen(x, y, z, screen);
      if (!screen.visible) continue;
      const d = (screen.x - px) ** 2 + (screen.y - py) ** 2;
      if (d < bestD) {
        bestD = d;
        best = { slot: enemy.slot, serial: enemy.serial };
      }
    }
    if (best) sink({ type: "mark", enemy: best });
  };
  canvasHost.addEventListener("pointerdown", onCanvasDown);
  canvasHost.addEventListener("pointerup", onCanvasUp);

  // ── A run: world and every presenter that reads it ──
  /** World options of a run at `pace` (E, and a and CV when they were measured). */
  const worldOptions = (pace: PaceHeader) => ({
    deck: deck!,
    typistWpm: pace.typistWpm,
    ...(pace.accuracyPm === undefined ? {} : { accuracyPm: pace.accuracyPm }),
    ...(pace.cvPm === undefined ? {} : { cvPm: pace.cvPm }),
    difficulty,
  });

  function buildRun(): Run {
    const pace = header!;
    const world = createWorld(stage, seed, worldOptions(pace));
    const layers = map.stage.layers;
    const onStage = (): Object3D[] => [...layers.ground.children, ...layers.actors.children, ...layers.fx.children];
    const before = new Set(onStage());
    const actors = createActors(map.stage, map.terrain, { models });
    heroes.reset();
    heroes.setLocator(actors);
    const telegraphs = createTelegraphs(map.stage, map.terrain, { locator: actors });
    const banners = createBanners(map.stage, map.terrain, { locator: actors, telegraphs });
    const hpbars = createHpBars(map.stage, { locator: actors, terrain: map.terrain });
    const fx = createFx(map.stage, { locator: actors, terrain: map.terrain, heroes, shake: (px) => map.rig.shake(px) });
    const tags = createTags(overlay!, map.stage.project, {
      gloss: learning.gloss,
      sizePct: options.tagSizePct === undefined ? undefined : Math.min(150, Math.max(80, options.tagSizePct)),
      // Thẻ Ôn opens on the last kill of a wave: that word's leaving tag and letter sparks would show the answer.
      quiet: () => run !== null && (run.review.isOpen || run.prelearn.isOpen),
    });
    const frame = createLearningFrame(overlay!, learning.gloss, { speak: learning.speak });
    const placement = createPlacementUi(overlay!, map.stage.project, sink, { onSlots: (visible, highlight) => map.paths.showSlots(visible, highlight) });
    const hud = createHud(overlay!, sink, {
      onPause: openMenu,
      onCameraReset: () => map.rig.reset(),
      // The break clock stands still while a learning panel is open (00 §4.5): the HUD says so.
      heldBy: () => (run?.review.isOpen ? "Review" : run?.prelearn.isOpen ? "Preview" : null),
    });
    const waveCard = createWaveCard(overlay!, sink);
    // The card's "Quái sắp vào từ các đường sáng": the coming wave's lanes light on the map (26/10 review).
    const laneCue = createLaneCue(map.paths);
    const strip = createShopStrip(overlay!, sink, { placement });
    const debut = createDebutCard(overlay!);
    const results = createResults(overlay!, {
      retry: restart,
      listen: (text) => learning.speak(text),
      gloss: learning.gloss,
      easierOffer: () => (lossStreak >= 2 && EASIER[difficulty] !== null ? DIFFICULTY_VI[EASIER[difficulty]!] : null),
      easier: () => {
        const next = EASIER[difficulty];
        if (next === null) return;
        difficulty = next;
        lossStreak = 0;
        restart();
        run?.hud.toast("Replay on " + DIFFICULTY_VI[next]);
      },
    });
    const hooks = {
      speak: (text: string) => learning.speak(text),
      recall: (text: string, correct: boolean, ms: number, answer: string) => {
        learning.recordRecall(text, correct, { responseMs: ms, userAnswer: answer });
        if (!correct) audio.learning("wrong");
      },
      send: sink,
    };
    // Học trước shows the word: copying it is not a recall (00 D14), so its answers go out with hintUsed.
    const prelearn = createPrelearn(overlay!, {
      ...hooks,
      recall: (text: string, correct: boolean, ms: number, answer: string) => {
        learning.recordRecall(text, correct, { responseMs: ms, userAnswer: answer, hintUsed: true });
        if (!correct) audio.learning("wrong");
      },
    });
    const review = createReviewCard(overlay!, hooks);
    const replay: ActionHandler = { handleAction: (action) => action === "replay" && learning.handleAction("replay") };
    return {
      world,
      header: pace,
      meter: new PaceMeter(),
      log: [],
      // actors first: the others read the positions it computes each frame.
      presenters: [actors, heroes, telegraphs, banners, hpbars, fx, tags, frame, placement, hud, waveCard, laneCue, strip, debut, results, audio],
      scene: { presenters: [actors, telegraphs, banners, hpbars, fx], roots: onStage().filter((root) => !before.has(root)) },
      handlers: [results, placement, strip, waveCard, hud, replay, map.rig],
      actors,
      fx,
      telegraphs,
      banners,
      hud,
      placement,
      frame,
      prelearn,
      review,
    };
  }

  /**
   * The last run's 3D views, off the stage but not yet disposed. three.js drops
   * a compiled GPU program once no material uses it, and some of the new run's
   * materials only appear with its first foe or telegraph; while the old ones
   * live, those find their program cached, so a retry links no shader (a
   * 270 ms frame before). They go at the next restart or with the app.
   */
  let retired: Presenter[] = [];

  /** Disposes `old`; with `retire`, its 3D views leave the stage now and are disposed at the next call. */
  function disposeRun(old: Run | null = run, retire = false): void {
    for (const presenter of retired) presenter.dispose();
    retired = [];
    if (!old) return;
    for (const presenter of old.presenters) {
      if (presenter === audio || presenter === heroes) continue;
      if (!retire || !old.scene.presenters.includes(presenter)) presenter.dispose();
    }
    if (retire) {
      for (const root of old.scene.roots) root.removeFromParent();
      retired = old.scene.presenters;
    }
    old.prelearn.dispose();
    old.review.dispose();
    if (old === run) {
      heroes.setLocator(undefined);
      run = null;
    }
  }

  function restart(): void {
    if (disposed || !deck) return;
    learning.flush();
    audio.resetRun();
    fastForward = false;
    countdownUntil = 0;
    if (victoryTurn !== null) map.rig.reset();
    victoryTurn = null;
    imeUntil = 0;
    const old = run;
    run = buildRun();
    disposeRun(old, true);
    router!.handlers.splice(0, router!.handlers.length, ...run.handlers);
  }

  // ── Events the app itself follows: Thẻ Ôn, flushes, the hurt edge ──
  /** A stage ended: its word timings go into the measured profile; a run on the measured speed follows it on retry. */
  function measureStage(world: World, won: boolean): void {
    if (!run) return;
    const safety = won && world.hero.hpMax > 0 ? world.hero.hp / world.hero.hpMax : 0;
    const measured = recordStage(safeLocalStorage, run.meter.sample(won ? "won" : "lost", world.stats, safety));
    if (measured !== null && header?.source === "measured") header = measuredHeader(measured);
  }

  function followEvents(events: readonly SimEvent[], now: number): void {
    if (!run) return;
    run.meter.onEvents(events);
    for (const event of events) {
      switch (event.type) {
        case "wave-end":
          learning.flush();
          // No Thẻ Ôn after the last wave: the results screen comes next.
          if (stage.unlocks.reviewCard && event.wave < stage.waves.length) {
            const items = learning.reviewItems(event.wave);
            lastReview = items.map((item) => item.text);
            if (items.length > 0) run.review.show(items);
          }
          break;
        case "phase":
          // The next wave is coming (a click on Gọi sớm): the card closes, nothing is lost.
          if (event.phase === "warning" && run.review.isOpen) run.review.handleAction("escape");
          break;
        case "victory":
        case "defeat":
          if (event.type === "victory") victoryTurn = { yawDeg: map.rig.yawDeg, zoom: map.rig.zoom, at: now };
          lossStreak = event.type === "defeat" ? lossStreak + 1 : 0;
          learning.flush();
          measureStage(run.world, event.type === "victory");
          run.placement.cancel();
          // The results screen owns the keys; an open panel would also freeze world time (telegraph fades).
          if (run.review.isOpen) run.review.handleAction("escape");
          if (run.prelearn.isOpen) run.prelearn.handleAction("escape");
          fastForward = false;
          break;
        case "hit":
          // A foe's blow darkens the edge (05 §5); Héo lan's seep (source "hero") tints it violet, so a beat that
          // takes HP is seen where the eyes are (test pass 27/10: only the HP bar moved).
          if (event.target.kind === "hero" && event.source.kind !== "hero") hurtUntil = now + 120;
          else if (event.target.kind === "hero" && event.amount > 0) {
            seepUntil = now + 420;
            seepStrong = event.amount * 20 >= run.world.hero.hpMax;
          }
          break;
        case "word-assigned":
          keepOutSoon = true;
          break;
        default:
          break;
      }
    }
  }

  /** Alt + →: only in a break, or with no live word and no foe in the word zone (00 §6, 06 §10). */
  function fastForwardAllowed(world: World): boolean {
    if (world.phase === "break") return true;
    if (world.phase !== "wave" && world.phase !== "warning") return false;
    if (world.words.live.some((word) => word !== null)) return false;
    const r = WORD_ZONE_U;
    return !world.enemies.list.some((enemy) => enemy.alive && enemy.x * enemy.x + enemy.z * enemy.z <= r * r);
  }

  /** Why Alt + → is refused now, in the player's terms (test pass 27/10: the old line named words only). */
  function fastForwardRefusal(world: World): string {
    if (world.phase !== "wave" && world.phase !== "warning") return "Fast forward: waves and breaks only";
    if (world.words.live.some((word) => word !== null)) return "Type all visible words before fast forwarding";
    return "Foes in the Word Zone: wait for their words";
  }

  const fallback = (action: string): boolean => {
    if (!run) return false;
    if (action === "escape") {
      openMenu();
      return true;
    }
    if (action === "fast-forward") {
      if (!fastForward && !fastForwardAllowed(run.world)) {
        run.hud.toast(fastForwardRefusal(run.world));
        return true;
      }
      fastForward = !fastForward;
      return true;
    }
    return false;
  };

  /** Pause overlay, countdown and the pause menu see a press first. */
  const intercept = (event: KeyboardEvent, action: string | null): boolean => {
    // The speed card takes every press while it is up (letters too: nothing types under it).
    // A bare Digit 0 has no KEYS action; on the card it picks the measured row.
    if (paceCard.isOpen) {
      const bare = !event.altKey && !event.shiftKey && !event.ctrlKey && !event.metaKey;
      return paceCard.handleAction(action ?? (bare && event.code === "Digit0" ? "carry-0" : null));
    }
    if (menuOpen) {
      if (action === "escape") closeMenu();
      else if (action === "tilt-up") selectMenu(menuIndex - 1);
      else if (action === "tilt-down") selectMenu(menuIndex + 1);
      else if (action === "enter") menuActions[menuIndex]?.run();
      return true;
    }
    if (veilMode !== "none" && liftVeil()) return true;
    if (countdownUntil > view.performance.now()) return true;
    void event;
    return false;
  };

  const paused = (now: number): boolean => menuOpen || paceCard.isOpen || veilMode === "focus" || countdownUntil > now || activePanel() !== null;

  // ── Frame ──
  function frame(info: FrameInfo): void {
    if (!run) return;
    const world = run.world;
    const now = info.now;
    if (lastFrameAt > 0) {
      stats.times.push(now - lastFrameAt);
      if (stats.times.length > 600) stats.times.shift();
    }
    lastFrameAt = now;
    stats.frames += 1;

    const events = world.events.drain();
    for (const event of events) {
      tally[event.type] = (tally[event.type] ?? 0) + 1;
      if (event.type === "telegraph") tally["telegraph:" + event.owner] = (tally["telegraph:" + event.owner] ?? 0) + 1;
      if (event.type === "telegraph" && event.owner === "enemy") {
        if (event.durationMs < telegraphMinMs) telegraphMinMs = event.durationMs;
        const foe = event.source.kind === "enemy" ? (world.enemies.list[event.source.slot]?.foe ?? "enemy") : event.source.kind;
        const seen = (telegraphByFoe[foe] ??= { n: 0, minMs: Infinity, shape: event.shape });
        seen.n += 1;
        seen.minMs = Math.min(seen.minMs, event.durationMs);
      }
    }
    learning.onEvents(events);
    if (keepOutSoon) {
      protectAt = 0;
      keepOutSoon = false;
    }
    followEvents(events, now);
    for (const presenter of run.presenters) presenter.onEvents(events, world);
    if (victoryTurn !== null) {
      // 05 §6.7 C1: the camera turns slowly round the dais and comes a little closer while the results wait.
      const t = Math.min(1, (now - victoryTurn.at) / VICTORY_HOLD_MS);
      if (t < 1) map.rig.setView({ yawDeg: victoryTurn.yawDeg + 28 * t, zoom: victoryTurn.zoom * (1 - 0.16 * t) });
    }
    map.update(info.dt);
    refreshKeepOut(now);
    for (const presenter of run.presenters) presenter.frame(world, info);
    map.render();
    run.fx.renderOverlay();

    // Keys typed since the last frame are on screen now.
    for (const at of pendingKeyTimes) {
      stats.keyLatency.push(view.performance.now() - at);
      if (stats.keyLatency.length > 2000) stats.keyLatency.shift();
    }
    pendingKeyTimes.length = 0;

    // Prep: Học trước once, then the setup.
    if (!prelearnShown && world.phase === "prep") {
      prelearnShown = true;
      const words = newWordsOf(deck!)
        .map((word) => ({ text: word.text, ...(learning.gloss(word.text) ?? { vi: "", ipa: "" }) }))
        .filter((word) => word.vi !== "");
      if (options.prelearn !== false && stage.unlocks.learnAhead && words.length > 0) run.prelearn.show(words.slice(0, 8));
    }

    const isPaused = paused(now);
    loop?.setPaused(isPaused);
    const wantAudioPause = menuOpen || paceCard.isOpen || veilMode === "focus";
    if (wantAudioPause !== audioPaused) {
      audioPaused = wantAudioPause;
      audio.setPaused(wantAudioPause);
    }
    audio.setListener(map.rig.target.x, map.rig.target.z, (map.rig.yawDeg * Math.PI) / 180);

    if (veilMode === "soft") setShown(veil, activePanel() === null);
    if (fastForward && !fastForwardAllowed(world)) fastForward = false;
    setShown(ffBadge, fastForward);
    hurt.classList.toggle("is-on", now < hurtUntil);
    seep.classList.toggle("is-on", now < seepUntil);
    seep.classList.toggle("is-strong", now < seepUntil && seepStrong);
    const lowHp = world.phase === "wave" && world.hero.hp > 0 && world.hero.hp * 100 < world.hero.hpMax * URGENT.heroHpPct;
    lowEdge.classList.toggle("is-on", lowHp);
    // The notice over the learning frame: the IME first, then low HP with a potion ready.
    const potion = Object.values(world.shop.held).some((count) => count > 0) && world.tick >= world.shop.consumableReadyAt;
    const noticeText = now < imeUntil ? "Turn off Vietnamese input (Unikey, Telex) to type English" : lowHp && potion ? "Hỏa Long low on HP: press " + keyLabel("consumable-1") + " for a Small Potion" : "";
    setShown(notice2, noticeText !== "" && !menuOpen && !paceCard.isOpen);
    if (notice2.textContent !== noticeText) notice2.textContent = noticeText;
    notice2.classList.toggle("is-ime", now < imeUntil);
    const left = countdownUntil - now;
    setShown(countdownNode, left > 0);
    if (left > 0) countdownNode.textContent = String(Math.ceil(left / 1000));
    // Words stay hidden while the game stands still for the menu or the 3-2-1; a learning panel covers the frame.
    const hushed = menuOpen || paceCard.isOpen || left > 0;
    setShown(hush, hushed);
    overlay!.classList.toggle("is-hushed", hushed);
    run.frame.setCovered(activePanel() !== null);
  }

  /**
   * Reads the UI rectangles damage numbers keep off (fx.numbers.protected).
   * Called before the presenters run, so the number field drops a number the
   * new rectangles cover before it is drawn. Read after them (until 25/10),
   * the field learnt the rectangles a frame late and __dh.numbersOverlaps()
   * found a number on one after the frame (dh-hitstop-keys on the Mac, one
   * sample a run). Between reads (250 ms) a tag can still move onto a number.
   */
  function refreshKeepOut(now: number): void {
    if (!run || now < protectAt) return;
    protectAt = now + PROTECT_EVERY_MS;
    const rects: { x: number; y: number; w: number; h: number }[] = [];
    for (const node of overlay!.querySelectorAll<HTMLElement>("[data-dh-avoid], [data-keepout], .kit-learning-frame, .dh-tag")) {
      if (node.hidden) continue;
      const r = node.getBoundingClientRect();
      if (r.width > 0 && r.height > 0) rects.push({ x: r.left, y: r.top, w: r.width, h: r.height });
    }
    run.fx.numbers.protected = rects;
  }

  const timeScale = (now: number): number => {
    if (!run) return 1;
    const stop = run.fx.timeScale(now);
    if (stop < 1) slowFrames += 1;
    return stop * (fastForward ? 2 : 1) * speed;
  };

  // ── Boot: deck, world, loop, router ──
  let ready = false;
  /** The first run, once the deck is in and the speed is known. */
  const begin = (): void => {
    if (disposed || run) return;
    run = buildRun();
    router!.handlers.push(...run.handlers);
    loop = createLoop({ step: () => run && step(run.world), frame, timeScale });
    loop.start();
    if (!doc.hasFocus()) {
      veilMode = "soft";
      veilText.textContent = "Click or press any key to start";
      veil.classList.add("is-soft");
      setShown(veil, true);
    }
    ready = true;
  };
  void learning.buildDeck(stage).then((built) => {
    if (disposed) return;
    deck = built;
    notice.remove();
    // The router first: the speed card answers to it before there is a run.
    router = createInputRouter(view, sink, {
      intercept,
      panel: activePanel,
      locked: () => (run ? run.world.words.lock >= 0 : false),
      fallback,
      // A notice over the learning frame, held until a letter reaches the game (test pass 27/10: an 11 px toast in a corner).
      onImeSign: () => {
        if (run) imeUntil = view.performance.now() + 8000;
      },
      now: () => view.performance.now(),
    });
    if (header !== null) begin();
    else
      askPace((picked, choice) => {
        header = picked;
        if (choice?.easy) difficulty = "easy";
        begin();
      });
  });

  const handle: DebugHandle = {
    get ready() {
      return ready;
    },
    world: () => run!.world,
    state: () => {
      const world = run?.world;
      if (!world) return { ready, paceCard: paceCard.isOpen };
      return {
        ready,
        pace: { ...run!.header, kPm: world.pace.kPm, marginPm: world.pace.marginPm, graceTicks: world.pace.graceTicks },
        paceCard: paceCard.isOpen,
        phase: world.phase,
        difficulty: world.difficulty,
        lossStreak,
        wave: world.wave,
        tick: world.tick,
        phaseEndsAt: world.phaseEndsAt,
        gold: world.economy.gold,
        heroHp: world.hero.hp,
        heroHpMax: world.hero.hpMax,
        live: world.enemies.live,
        lock: world.words.lock,
        chain: world.words.chain,
        rage: world.combat.rage,
        kills: world.stats.kills,
        keys: world.stats.keys,
        keysToSim,
        keysToPanels,
        routerLetters: router?.stats.letters ?? 0,
        swallowed: router?.stats.swallowed ?? 0,
        words: world.stats.words,
        grades: [...world.stats.grades],
        paused: paused(view.performance.now()),
        menuOpen,
        veil: veilMode,
        countdown: countdownUntil > view.performance.now(),
        fastForward,
        placement: run!.placement.mode + ":" + (run!.placement.item ?? ""),
        panel: handle.panel(),
        slots: world.slots.map((slot) => (slot.item ? slot.def.id + "=" + slot.item + "@" + slot.level : null)).filter(Boolean),
        held: { ...world.shop.held },
        heroBuys: { ...world.shop.heroBuys },
        steps: loop?.steps ?? 0,
        commands: run!.log.length,
        banners: { carried: run!.banners.carried, carriedPlaceholders: run!.banners.carriedPlaceholders, planted: run!.banners.planted, named: run!.banners.named },
        layers: { actors: map.stage.layers.actors.children.length, fx: map.stage.layers.fx.children.length, overlay: overlay!.childElementCount },
      };
    },
    words: () => {
      const world = run!.world;
      const out: ReturnType<DebugHandle["words"]> = [];
      const screen: ScreenPoint = { x: 0, y: 0, visible: false };
      world.words.live.forEach((word, slot) => {
        if (!word) return;
        let sx = -1;
        let sy = -1;
        let visible = false;
        const target = word.target && word.target.kind === "enemy" ? { slot: word.target.slot, serial: word.target.serial } : null;
        if (target) {
          const enemy = world.enemies.list[target.slot];
          if (enemy && enemy.alive && enemy.serial === target.serial) {
            map.worldToScreen(uToM(enemy.x), uToM(enemy.y) + 1, uToM(enemy.z), screen);
            sx = screen.x;
            sy = screen.y;
            visible = screen.visible;
          }
        }
        out.push({ slot, text: word.text, kind: word.kind, typed: word.typed, target, sx, sy, visible });
      });
      return out;
    },
    foes: () => {
      const world = run!.world;
      const screen: ScreenPoint = { x: 0, y: 0, visible: false };
      return world.enemies.list
        .filter((enemy) => enemy.alive)
        .map((enemy) => {
          map.worldToScreen(uToM(enemy.x), uToM(enemy.y) + 0.8, uToM(enemy.z), screen);
          return { slot: enemy.slot, serial: enemy.serial, foe: enemy.foe, hp: enemy.hp, hpMax: enemy.hpMax, word: enemy.word, x: uToM(enemy.x), z: uToM(enemy.z), sx: screen.x, sy: screen.y, visible: screen.visible };
        });
    },
    hash: () => hashWorldHex(run!.world),
    replayCheck: () => {
      const world = run!.world;
      const copy = createWorld(stage, seed, worldOptions(run!.header));
      runLog(copy, run!.log, world.tick);
      const live = hashWorldHex(world);
      const replay = hashWorldHex(copy);
      return { live, replay, same: live === replay, commands: run!.log.length };
    },
    perf: () => {
      const times = [...stats.times].sort((a, b) => a - b);
      const mean = times.reduce((a, b) => a + b, 0) / Math.max(1, times.length);
      const lat = stats.keyLatency;
      const s = map.stage.stats();
      return {
        frames: stats.frames,
        meanMs: mean,
        p95Ms: times[Math.floor(times.length * 0.95)] ?? 0,
        maxMs: times[times.length - 1] ?? 0,
        drawCalls: s.drawCalls,
        triangles: s.triangles,
        keyLatencyMaxMs: lat.length ? Math.max(...lat) : 0,
        keyLatencyMeanMs: lat.length ? lat.reduce((a, b) => a + b, 0) / lat.length : 0,
        keys: lat.length,
      };
    },
    numbersOverlaps: () => run!.fx.numbers.overlaps(),
    numbersTouching: () => {
      const field = run!.fx.numbers;
      const a = { x: 0, y: 0, w: 0, h: 0 };
      const b = { x: 0, y: 0, w: 0, h: 0 };
      let touching = 0;
      for (let i = 0; i < field.alive.length; i += 1) {
        if (field.alive[i] !== 1) continue;
        field.box(i, a);
        for (let j = i + 1; j < field.alive.length; j += 1) {
          if (field.alive[j] !== 1) continue;
          field.box(j, b);
          if (a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y) touching += 1;
        }
      }
      return touching;
    },
    numberLayer: () => (run ? run.fx : null),
    setSpeed: (value) => {
      if (dev) speed = Math.min(16, Math.max(0.25, value));
    },
    // Keys sent here were pressed now: key latency counts from this call (test pass 27/10: it counted from the last real key).
    send: (command) => sinkAt(command, view.performance.now()),
    action: (name) => router?.dispatch(name) ?? false,
    restart,
    panel: () => (run?.prelearn.isOpen ? "prelearn" : run?.review.isOpen ? "review" : menuOpen ? "menu" : null),
    review: () => [...lastReview],
    events: () => ({ tally: { ...tally }, telegraphMinMs: Number.isFinite(telegraphMinMs) ? telegraphMinMs : null, byFoe: structuredClone(telegraphByFoe), slowFrames, telegraphsLive: run?.telegraphs.live ?? 0 }),
    foeSizes: () => {
      if (!run) return [];
      const base = new Vector3();
      const top = new Vector3();
      const a: ScreenPoint = { x: 0, y: 0, visible: false };
      const b: ScreenPoint = { x: 0, y: 0, visible: false };
      const c: ScreenPoint = { x: 0, y: 0, visible: false };
      const out: { foe: string; px: number; widthPx: number; distM: number }[] = [];
      for (const enemy of run.world.enemies.list) {
        if (!enemy.alive) continue;
        if (!run.actors.locate(enemy.slot, enemy.serial, "base", base) || !run.actors.locate(enemy.slot, enemy.serial, "top", top)) continue;
        map.worldToScreen(base.x, base.y, base.z, a);
        map.worldToScreen(top.x, top.y, top.z, b);
        if (!a.visible || !b.visible) continue;
        // As drawn (foe-look.ts: the tier's draw scale), the same size dh-scale measures.
        const [drawnW, , drawnL] = foeDrawnSize(enemy.foe as FoeId);
        const halfW = Math.max(drawnW, drawnL) / 2;
        map.worldToScreen(base.x + halfW, base.y, base.z, c);
        out.push({ foe: enemy.foe, px: Math.abs(a.y - b.y), widthPx: Math.abs(c.x - a.x) * 2, distM: Math.hypot(base.x, base.z) });
      }
      return out;
    },
    fxStorm: (count) => {
      if (!run) return 0;
      const world = run.world;
      const foes = world.enemies.list.filter((enemy) => enemy.alive);
      const fake: SimEvent[] = [];
      for (let k = 0; k < count; k += 1) {
        const foe = foes[k % Math.max(1, foes.length)];
        const x = foe ? uToM(foe.x) : (k % 7) - 3;
        const z = foe ? uToM(foe.z) : -8 - (k % 5);
        const target = foe ? { kind: "enemy" as const, slot: foe.slot, serial: foe.serial } : { kind: "enemy" as const, slot: 0, serial: 0 };
        fake.push({ type: "hit", tick: world.tick, target, source: { kind: "hero" }, amount: 60 + k, damageType: "word", tier: k % 2 === 0 ? 5 : 4, grade: "perfect", x, z, hpLeft: 1 });
      }
      run.fx.onEvents(fake, world);
      return fake.length;
    },
    setView: (next, snap = true) => map.rig.setView(next, snap),
    project: (x, y, z) => map.worldToScreen(x, y, z),
  };
  if (dev || new URLSearchParams(view.location.search).get("debug") === "1") view.__dh = handle;

  return {
    dispose(): void {
      disposed = true;
      learning.flush();
      loop?.stop();
      router?.dispose();
      disposeRun();
      paceCard.dispose();
      heroes.dispose();
      models.dispose();
      audio.dispose();
      learning.dispose();
      stopMusicWatch();
      bridge.dispose();
      view.removeEventListener("blur", onBlur);
      doc.removeEventListener("visibilitychange", onVisibility);
      view.removeEventListener("pointerdown", onPointerDown, { capture: true });
      canvasHost.removeEventListener("pointerdown", onCanvasDown);
      canvasHost.removeEventListener("pointerup", onCanvasUp);
      map.dispose();
      overlay.replaceChildren();
      if (view.__dh === handle) delete view.__dh;
    },
  };
}

src/app/learning.ts:
/**
 * Learning glue (01 §6): loads vocabulary (kit/vocab, /vocabulary/), asks
 * shared learning through the portal bridge (kit/learning, gameId
 * "dragon-hold"), builds the WordDeck (typing/deck.ts), and turns
 * word-complete events into learning events (one scored event per word per
 * run, D14), queued locally when the portal is absent. It also owns the one
 * pronunciation channel (01 §6.4) and Tab replay.
 * Owner: typing-learning (LANES.md).
 */
import { ECONOMY, LEARNING } from "../content/rules";
import type { ActivityType, DeckWord, SimEvent, StageDef, WordDeck } from "../content/types";
import { buildCombatLearningEvent, normalizeLearningEntityId, type LearningBridge, type LearningEvent } from "../kit/learning";
import { createRng, safeLocalStorage } from "../kit/platform";
import { speakEnglish } from "../kit/speech";
import { filterVocabularyEntries, loadVocabularyIndex, loadVocabularyLevel, textHasBlockedWord, type VocabularyEntry } from "../kit/vocab";
import { buildWordDeck, isDeckText, type DeckCandidate } from "../typing/deck";
import type { Gloss } from "../ui/learning-frame";
import { createPortalBridge } from "./portal";

const GAME_ID = LEARNING.gameId;
/** Recall activities: always sent (01 §6.6), and a right answer without a hint counts toward hiding the meaning (01 §6.3). */
const RECALLS: ReadonlySet<string> = new Set(["meaning-recall", "listening", "review-card"]);

/**
 * One rule for "a right recall" (01 §6.3, 00 D14), on this device and in the
 * portal's samples: a right answer in a recall activity with no hint shown.
 * Học trước goes out as `review-card` with hintUsed (its word, IPA and
 * meaning show while it is typed, 01 §6.3, §6.6), so it is never one.
 */
export const isRightRecall = (activityType: unknown, result: unknown, hintUsed: unknown): boolean =>
  RECALLS.has(String(activityType)) && result === "correct" && hintUsed !== true;

const STORE_KEY = GAME_ID + ":words:v1";
const LEVEL_KEY = GAME_ID + ":vocab-level";

/** What the client keeps per word on this device (fallback when the portal cannot be asked, 01 §6.8). */
export interface LocalWordRecord {
  typedRight: number;
  typedWrong: number;
  recalls: number;
  /** ms since epoch of the last meeting. */
  lastSeen: number;
}

/** What the game needs of a shared-learning record (01 §6.1, §6.3). */
export interface WordRecord {
  readonly mastery: number;
  readonly due: boolean;
  readonly recalls: number;
}

/** Pronunciation settings (01 §6.4): off, new words only, new and weak words (default), every word typed. */
export type PronounceMode = "off" | "new" | "new-weak" | "all";

export interface PronounceRequest {
  readonly text: string;
  /** 0 listening, 1 new word, 2 weak word, 3 any other (01 §6.4 order). */
  readonly priority: number;
  readonly at: number;
}

/**
 * The one pronunciation channel (01 §6.4): two playbacks ≥ 2.5 s apart, a
 * queued word older than 2 s is dropped, listening words first, then new,
 * then weak. Tab replays play at once.
 */
export class Pronouncer {
  private queue: PronounceRequest[] = [];
  private lastAt = Number.NEGATIVE_INFINITY;
  /** Off while a boss seal window or a guide line holds the channel. */
  blocked = false;

  constructor(private readonly speak: (text: string) => void, private readonly now: () => number) {}

  request(text: string, priority: number): void {
    if (this.queue.some((item) => item.text === text)) return;
    this.queue.push({ text, priority, at: this.now() });
    this.tick();
  }

  /** Plays `text` now (Tab), resetting the gap. */
  playNow(text: string): void {
    this.queue = this.queue.filter((item) => item.text !== text);
    this.lastAt = this.now();
    this.speak(text);
  }

  tick(): void {
    const now = this.now();
    this.queue = this.queue.filter((item) => now - item.at <= LEARNING.pronounceDropMs);
    if (this.blocked || this.queue.length === 0 || now - this.lastAt < LEARNING.pronounceGapMs) return;
    this.queue.sort((a, b) => a.priority - b.priority || a.at - b.at);
    const next = this.queue.shift()!;
    this.lastAt = now;
    this.speak(next.text);
  }

  get waiting(): number {
    return this.queue.length;
  }
}

/** One word's meetings in this stage (Sổ Từ Ải, Thẻ Ôn picks; 01 §6.5). */
export interface StageWord {
  readonly text: string;
  readonly isNew: boolean;
  wave: number;
  count: number;
  sloppy: boolean;
  hintUsed: boolean;
  errors: number;
}

/** A Thẻ Ôn question (01 §6.5). */
export interface ReviewItem {
  readonly text: string;
  readonly vi: string;
  readonly ipa: string;
  /** "listen": hear then type; "meaning": read the meaning then type. */
  readonly mode: "listen" | "meaning";
}

export interface LearningClient {
  /** The stage's deck; resolves with a cold-start deck when the portal does not answer in 2 s. */
  buildDeck(stage: StageDef): Promise<WordDeck>;
  readonly gloss: Gloss;
  onEvents(events: readonly SimEvent[]): void;
  /** Sends queued events now (wave end, run end, tab close). */
  flush(): void;
  dispose(): void;
  /** The deck the last buildDeck made (null before). */
  readonly deck: WordDeck | null;
  /**
   * A recall-activity answer (Học trước, Thẻ Ôn), `review-card` unless
   * `activity` says otherwise: always sent (01 §6.6). Học trước passes
   * hintUsed, since its meaning and IPA show while the word is typed
   * (01 §6.3): sent as such, it never counts as a right recall (00 D14: copy
   * typing is not remembering), here or when the portal sends it back.
   */
  recordRecall(text: string, correct: boolean, detail?: { activity?: ActivityType; responseMs?: number; hintUsed?: boolean; userAnswer?: string }): void;
  /** Up to 3 Thẻ Ôn questions from `wave`: Ẩu words, then words typed with a hint, then new words (01 §6.5). */
  reviewItems(wave: number): ReviewItem[];
  /** Every word met this stage, for Sổ Từ Ải. */
  stageWords(): readonly StageWord[];
  /** Tab (action "replay"): hears the locked word, else the last one typed; returns true when it played. */
  handleAction(action: string): boolean;
  /** Plays a word at once (Học trước, Thẻ Ôn, a speaker icon). */
  speak(text: string): void;
  readonly pronouncer: Pronouncer;
  /** Events waiting for the next batch. */
  readonly pending: number;
}

export interface LearningClientOptions {
  readonly bridge?: LearningBridge;
  /** Entries of these vocabulary levels, sensitive words already out (tests pass a fake). */
  readonly loadEntries?: (levels: readonly number[]) => Promise<VocabularyEntry[]>;
  /** Vocabulary level of the stage; default the saved one, else 1. */
  readonly vocabLevel?: number;
  /** Child profile: mature words out too (00 D15). */
  readonly excludeMature?: boolean;
  readonly storage?: { readJson(key: string): unknown; writeJson(key: string, value: unknown): boolean };
  readonly now?: () => number;
  readonly speak?: (text: string) => void;
  readonly pronounce?: PronounceMode;
  /** Batch timer; default window.setInterval every 5 s (none outside a browser). */
  readonly every?: (ms: number, run: () => void) => () => void;
}

/** Shared-learning lookup results in either shape the portal may answer with: { items: [...] }, { records: {...} } or a list. */
export function parseLookup(value: unknown, now: number): Map<string, WordRecord> {
  const out = new Map<string, WordRecord>();
  const object = value !== null && typeof value === "object" ? (value as Record<string, unknown>) : null;
  let rows: unknown[] = [];
  if (Array.isArray(value)) rows = value;
  else if (object && Array.isArray(object["items"])) rows = object["items"] as unknown[];
  else if (object && object["records"] !== null && typeof object["records"] === "object") {
    rows = Object.entries(object["records"] as Record<string, unknown>).map(([entityId, record]) => ({ entityId, ...(record as object) }));
  }
  for (const row of rows) {
    if (row === null || typeof row !== "object") continue;
    const record = row as Record<string, unknown>;
    const id = record["entityId"] ?? record["wordKey"];
    if (typeof id !== "string") continue;
    const mastery = typeof record["mastery"] === "number" ? Math.max(0, Math.min(100, record["mastery"])) : 0;
    const next = typeof record["nextReviewAt"] === "string" ? Date.parse(record["nextReviewAt"]) : Number.NaN;
    const samples = [record["recentAnswers"], record["recentSamples"]].flatMap((list) => (Array.isArray(list) ? list : []));
    const recalls = samples.filter((sample) => {
      const s = sample as Record<string, unknown> | null;
      return s !== null && typeof s === "object" && isRightRecall(s["activityType"], s["result"], s["hintUsed"]);
    }).length;
    out.set(normalizeLearningEntityId(id), { mastery, due: (Number.isFinite(next) && next <= now) || mastery < LEARNING.weakMastery, recalls });
  }
  return out;
}

/** A device record as a shared-learning record: copy typing never lifts it past 60 (01 §6.8), recalls do. */
export function localRecord(record: LocalWordRecord, now: number): WordRecord {
  const mastery = Math.max(0, Math.min(100, Math.min(60, 25 * record.typedRight) + 15 * record.recalls - 10 * record.typedWrong));
  const stale = now - record.lastSeen > 24 * 3600 * 1000;
  return { mastery, due: mastery < LEARNING.weakMastery || (stale && mastery < LEARNING.knownMastery), recalls: record.recalls };
}

/** Vocabulary entries → deck candidates: one a–z word of 3–10 letters, no blocked word (00 D15), first spelling only. */
export function candidatesFrom(
  entries: readonly (VocabularyEntry & { level?: number })[],
  records: ReadonlyMap<string, WordRecord>,
  excludeMature = false,
): DeckCandidate[] {
  const seen = new Set<string>();
  const out: DeckCandidate[] = [];
  for (const entry of filterVocabularyEntries(entries, { excludeMature })) {
    const text = normalizeLearningEntityId(entry.en);
    if (!isDeckText(text) || seen.has(text) || textHasBlockedWord(text, { excludeMature })) continue;
    seen.add(text);
    const record = records.get(text);
    out.push({ text, level: entry.level ?? 1, isNew: record === undefined, mastery: record?.mastery ?? 0, due: record?.due ?? false, recalls: record?.recalls ?? 0 });
  }
  return out;
}

/** A learning event for a typed word (01 §6.6): correct only with no wrong key. */
export function typedWordEvent(
  event: Extract<SimEvent, { type: "word-complete" }>,
  replayUsed: boolean,
  occurredAt: string,
): LearningEvent {
  const base = buildCombatLearningEvent({ gameId: GAME_ID, entry: { id: event.text, en: event.text, vi: "", ipa: "" }, perfect: event.errors === 0, occurredAt });
  return { ...base, activityType: event.activity, responseMs: Math.max(0, Math.round(event.responseMs)), hintUsed: event.hintUsed, replayUsed };
}

async function defaultEntries(levels: readonly number[], excludeMature: boolean): Promise<VocabularyEntry[]> {
  const index = await loadVocabularyIndex();
  const lists = await Promise.all(
    levels
      .filter((level) => index.levels.some((item) => item.level === level))
      .map(async (level) => (await loadVocabularyLevel(level, index, { excludeMature })).map((entry) => ({ ...entry, level }))),
  );
  return lists.flat();
}

const browser = typeof window !== "undefined";

export function createLearningClient(options: LearningClientOptions = {}): LearningClient {
  const now = options.now ?? (() => Date.now());
  const storage = options.storage ?? safeLocalStorage;
  const bridge = options.bridge ?? createPortalBridge();
  const excludeMature = options.excludeMature ?? false;
  const mode: PronounceMode = options.pronounce ?? "new-weak";
  const speakNow = options.speak ?? ((text: string) => (browser ? speakEnglish(text, { enabled: true, rate: 0.9, volume: 1 }) : undefined));
  const pronouncer = new Pronouncer((text) => {
    if (mode !== "off") speakNow(text);
  }, now);
  const glossMap = new Map<string, { vi: string; ipa: string }>();
  const local: Record<string, LocalWordRecord> = (() => {
    const raw = storage.readJson(STORE_KEY);
    return raw !== null && typeof raw === "object" && !Array.isArray(raw) ? (raw as Record<string, LocalWordRecord>) : {};
  })();
  const byText = new Map<string, DeckWord>();
  const slots = new Map<number, string>();
  const replayed = new Set<string>();
  const firstLocked = new Set<string>();
  const stage = new Map<string, StageWord>();
  let pending: LearningEvent[] = [];
  let deck: WordDeck | null = null;
  let wave = 0;
  let locked = -1;
  let lastTyped = "";
  let disposed = false;

  const saveLocal = () => storage.writeJson(STORE_KEY, local);
  const touch = (text: string): LocalWordRecord => (local[text] ??= { typedRight: 0, typedWrong: 0, recalls: 0, lastSeen: now() });
  const flush = (): void => {
    if (pending.length === 0) return;
    const batch = pending;
    pending = [];
    for (const event of batch) bridge.sendAttempt(event);
    saveLocal();
  };
  const stop = options.every
    ? options.every(LEARNING.batchMs, flush)
    : browser
      ? (() => {
          const id = window.setInterval(flush, LEARNING.batchMs);
          return () => window.clearInterval(id);
        })()
      : () => {};
  const onHide = () => flush();
  if (browser) window.addEventListener("pagehide", onHide);

  /** Weak: mastery under 40 (01 §6.4). */
  const isWeak = (text: string) => (byText.get(text)?.mastery ?? 0) < LEARNING.weakMastery;
  const isNewWord = (text: string) => byText.get(text)?.group === "new";

  /** New words when first locked and when typed; weak words when typed; every typed word in "all" (01 §6.4). */
  const autoPronounce = (text: string, typed: boolean) => {
    if (mode === "off") return;
    if (isNewWord(text)) pronouncer.request(text, 1);
    else if (!typed) return;
    else if (mode !== "new" && isWeak(text)) pronouncer.request(text, 2);
    else if (mode === "all") pronouncer.request(text, 3);
  };

  const client: LearningClient = {
    get deck() {
      return deck;
    },
    get pending() {
      return pending.length;
    },
    pronouncer,
    gloss: (text) => glossMap.get(text) ?? null,

    async buildDeck(stageDef: StageDef): Promise<WordDeck> {
      const saved = Number(storage.readJson(LEVEL_KEY));
      const level = Math.max(1, Math.round(options.vocabLevel ?? (Number.isFinite(saved) && saved > 0 ? saved : 1)));
      const levels = [level, level + 1];
      let entries: (VocabularyEntry & { level?: number })[] = [];
      try {
        entries = await (options.loadEntries ? options.loadEntries(levels) : defaultEntries(levels, excludeMature));
      } catch (error) {
        console.warn("dragon-hold: vocabulary did not load", error);
      }
      for (const entry of entries) {
        const text = normalizeLearningEntityId(entry.en);
        if (!glossMap.has(text)) glossMap.set(text, { vi: entry.vi, ipa: entry.ipa });
      }
      const texts = [...new Set(entries.map((entry) => normalizeLearningEntityId(entry.en)).filter(isDeckText))];
      let records = new Map<string, WordRecord>();
      try {
        records = parseLookup(await bridge.lookup(texts.slice(0, 200)), now());
      } catch {
        // No portal, or it did not answer in 2 s: this device's records stand in (01 §6.1, §6.8).
        for (const text of texts) if (local[text]) records.set(text, localRecord(local[text]!, now()));
      }
      // Recalls counted on this device add to what the portal knows (its lookup may lack recent samples).
      for (const [text, record] of records) {
        const mine = local[text]?.recalls ?? 0;
        if (mine > record.recalls) records.set(text, { ...record, recalls: mine });
      }
      const rng = createRng((stageDef.seed ^ 0x5eed) >>> 0);
      deck = buildWordDeck(candidatesFrom(entries, records, excludeMature), level, (min, max) => rng.words.int(min, max), {
        newMax: stageDef.type === "boss" ? LEARNING.newPerBossStage : LEARNING.newPerStage,
      });
      byText.clear();
      for (const word of deck.words) byText.set(word.text, word);
      stage.clear();
      firstLocked.clear();
      replayed.clear();
      return deck;
    },

    onEvents(events: readonly SimEvent[]): void {
      for (const event of events) {
        switch (event.type) {
          case "wave-start":
            wave = event.wave;
            break;
          case "word-assigned":
            slots.set(event.word, event.text);
            break;
          case "word-progress": {
            if (event.word < 0 || event.key === "pair" || (event.key === "switch" && event.typed === 0)) break;
            if (event.key === "back" && event.typed === 0) {
              if (locked === event.word) locked = -1;
              break;
            }
            if (locked === event.word) break;
            locked = event.word;
            const text = slots.get(event.word);
            // A new word is heard when first locked in the stage (01 §6.4).
            if (text !== undefined && isNewWord(text) && !firstLocked.has(text)) {
              firstLocked.add(text);
              autoPronounce(text, false);
            }
            break;
          }
          case "word-released":
            slots.delete(event.word);
            if (locked === event.word) locked = -1;
            break;
          case "word-complete": {
            lastTyped = event.text;
            const record = touch(event.text);
            record.lastSeen = now();
            if (event.errors === 0) record.typedRight += 1;
            else record.typedWrong += 1;
            const entry = stage.get(event.text) ?? { text: event.text, isNew: isNewWord(event.text), wave, count: 0, sloppy: false, hintUsed: false, errors: 0 };
            entry.wave = wave;
            entry.count += 1;
            entry.sloppy ||= event.grade === "sloppy";
            entry.hintUsed ||= event.hintUsed;
            entry.errors += event.errors;
            stage.set(event.text, entry);
            if (event.scored) pending.push(typedWordEvent(event, replayed.has(event.text), new Date(now()).toISOString()));
            autoPronounce(event.text, true);
            break;
          }
          case "wave-end":
          case "victory":
          case "defeat":
            flush();
            break;
          default:
            break;
        }
      }
      pronouncer.tick();
    },

    flush,

    recordRecall(text, correct, detail = {}) {
      const record = touch(text);
      record.lastSeen = now();
      const activityType: ActivityType = detail.activity ?? "review-card";
      const hintUsed = detail.hintUsed ?? false;
      // Only a real recall hides the meaning later (01 §6.3, D14); a copy with the answer shown does not.
      if (isRightRecall(activityType, correct ? "correct" : "wrong", hintUsed)) record.recalls += 1;
      const base = buildCombatLearningEvent({ gameId: GAME_ID, entry: { id: text, en: text, vi: "", ipa: "" }, perfect: correct, occurredAt: new Date(now()).toISOString() });
      pending.push({
        ...base,
        activityType,
        responseMs: Math.max(0, Math.round(detail.responseMs ?? 0)),
        hintUsed,
        replayUsed: replayed.has(text),
        ...(detail.userAnswer !== undefined ? { userAnswer: detail.userAnswer } : {}),
      });
    },

    reviewItems(forWave: number): ReviewItem[] {
      const words = [...stage.values()].filter((word) => word.wave === forWave);
      const ranked = [
        ...words.filter((word) => word.sloppy),
        ...words.filter((word) => !word.sloppy && word.hintUsed),
        ...words.filter((word) => !word.sloppy && !word.hintUsed && word.isNew),
      ];
      return ranked.slice(0, ECONOMY.reviewCardQuestions).map((word, index) => {
        const gloss = glossMap.get(word.text);
        return { text: word.text, vi: gloss?.vi ?? "", ipa: gloss?.ipa ?? "", mode: index % 2 === 0 ? "listen" : "meaning" };
      });
    },

    stageWords: () => [...stage.values()],

    handleAction(action: string): boolean {
      if (action !== "replay") return false;
      const text = (locked >= 0 ? slots.get(locked) : undefined) ?? lastTyped;
      if (text === "") return false;
      replayed.add(text);
      pronouncer.playNow(text);
      return true;
    },

    speak(text: string): void {
      pronouncer.playNow(text);
    },

    dispose(): void {
      if (disposed) return;
      disposed = true;
      flush();
      stop();
      if (browser) window.removeEventListener("pagehide", onHide);
      bridge.dispose();
    },
  };
  return client;
}

/** Saves the player's vocabulary level for the next deck. */
export function saveVocabLevel(level: number, storage: { writeJson(key: string, value: unknown): boolean } = safeLocalStorage): void {
  storage.writeJson(LEVEL_KEY, Math.max(1, Math.round(level)));
}

src/app/portal.ts:
import { LEARNING } from "../content/rules";
import { createLearningBridge, type BridgeHost, type LearningBridge, type LearningBridgeOptions } from "../kit/learning";

/** An optional build-time destination; paths, queries and fragments stay intact. */
export function portalHome(value: string | undefined): string | null {
  if (!value?.trim()) return null;
  try {
    const url = new URL(value.trim());
    if (!["https:", "http:"].includes(url.protocol) || url.username || url.password) throw new Error("Invalid portal URL");
    return url.href;
  } catch {
    throw new TypeError("VITE_PORTAL_URL must be an absolute HTTP(S) URL without credentials");
  }
}

// Without a configured portal, framing must not flush the local learning queue.
const standaloneHost: BridgeHost = {
  parent: null,
  addEventListener: () => {},
  removeEventListener: () => {},
  setTimeout: (callback, ms) => globalThis.setTimeout(callback, ms),
  clearTimeout: (handle) => globalThis.clearTimeout(handle as ReturnType<typeof setTimeout>),
  now: () => Date.now(),
};

export function createPortalBridge(options: Omit<LearningBridgeOptions, "gameId" | "parentOrigin"> = {}): LearningBridge {
  const home = portalHome(import.meta.env.VITE_PORTAL_URL);
  return createLearningBridge({
    ...options,
    gameId: LEARNING.gameId,
    parentOrigin: home ? new URL(home).origin : "",
    host: home ? options.host : standaloneHost,
  });
}

src/ui/debut-card.ts:
/**
 * Debut cards (02 §1.5: "loài mới có thẻ góc 3 s … làm gì, khắc chế"): the
 * first time a species walks onto the field a small card in the top-right
 * corner names it, says what it does and what counters it, for 3 s, without
 * pausing. A general's card wears its crown (02 §3.4 intro). Each species is
 * introduced at most SHOWN_MAX times per player (kept in local storage), once
 * a run. Test passes 26–27/10: new foes (Ong Gai, Yêu Rêu Cung, Heo, Sói, G01)
 * came with only "Heo ×1" on the wave card.
 * Owner: ui (LANES.md).
 */
import type { FrameInfo, Presenter } from "../app/contracts";
import { ENEMIES } from "../content/data/enemies";
import { GENERALS } from "../content/data/generals";
import type { FoeId, SimEvent } from "../content/types";
import { safeLocalStorage } from "../kit/platform";
import type { World } from "../sim/world";
import { el, foeIcon, icon, keyLabel, setShown, setText } from "./skin";

/** What each M0 species does and what beats it, in one line each (02 §2, §3; 03 for our side). */
export const DEBUT_LINES: Readonly<Partial<Record<FoeId, { readonly does: string; readonly counter: string }>>> = {
  "moss-grunt": { does: "Walks to the platform and slashes Hỏa Long.", counter: "Type its word; Grove Warden can block it." },
  "thorn-ant": { does: "The swarm shares one word: type it to hit them all.", counter: "Pine Bomb, Fire Breath." },
  "thorn-wasp": { does: "Flies along Sky Lane and fires from 10 m away; ground traps cannot hit it.", counter: "Net Launcher grounds it." },
  "moss-archer": { does: "Stops 12 m away and fires at Hỏa Long until defeated.", counter: "Type it first; Sky Fire hits the group." },
  "tusk-boar": { does: "Marks a red line, then charges the platform.", counter: "Grove Warden blocks it; Spikes slow it." },
  "blight-wolf": { does: "Runs in fast packs and leaps past blockers.", counter: "Spikes slow them; type each wolf early." },
  "moss-banner": { does: "A general that plants a Banner: foes within 5 m deal 25% more damage.", counter: "Type the Banner word to remove it; word chains strip the aura." },
};

/** A card stays this long (02 §1.5: 3 s). */
export const DEBUT_MS = 3000;
/** A queued card older than this is dropped (a general's never): it would name a foe long after it came. */
export const DEBUT_STALE_MS = 6000;
/** Introductions per species per player, across runs. */
export const SHOWN_MAX = 3;
const STORE_KEY = "dragon-hold.debuts";

/** How many times each species was introduced (storage-safe: an unreadable store is empty). */
function readShown(): Record<string, number> {
  try {
    const raw = JSON.parse(safeLocalStorage.getItem(STORE_KEY) ?? "{}") as unknown;
    return raw !== null && typeof raw === "object" ? (raw as Record<string, number>) : {};
  } catch {
    return {};
  }
}

/** The species a batch of events brings onto the field for the first time this run, in order. */
export function debutsIn(events: readonly SimEvent[], seen: Set<FoeId>, shown: Readonly<Record<string, number>>): FoeId[] {
  const out: FoeId[] = [];
  for (const event of events) {
    if (event.type !== "spawn" || seen.has(event.foe)) continue;
    seen.add(event.foe);
    if (DEBUT_LINES[event.foe] && (shown[event.foe] ?? 0) < SHOWN_MAX) out.push(event.foe);
  }
  return out;
}

/** A species waiting for its card, and when it was queued (0: stamp it at the next frame). */
export interface QueuedDebut {
  readonly foe: FoeId;
  at: number;
}

/**
 * The next card to show from `queue` at `now`, or null; drops stale cards
 * (a fast-forward or a crowded first peak can queue several: a card naming a
 * foe 10 s after it came reads wrong) but never a general's, and shows a
 * general first so it does not wait behind its escort.
 */
export function nextDebut(queue: QueuedDebut[], now: number): FoeId | null {
  for (let k = queue.length - 1; k >= 0; k -= 1) {
    const item = queue[k]!;
    if (item.at <= 0) item.at = now;
    else if (!(item.foe in GENERALS) && now - item.at > DEBUT_STALE_MS) queue.splice(k, 1);
  }
  if (queue.length === 0) return null;
  const general = queue.findIndex((item) => item.foe in GENERALS);
  return queue.splice(general >= 0 ? general : 0, 1)[0]!.foe;
}

export function createDebutCard(root: HTMLElement): Presenter {
  const doc = root.ownerDocument;
  const card = el(doc, "section", "dh-panel dh-debut");
  card.dataset.ui = "debut";
  // Word tags keep off it (app keep-out rectangles) like the HUD panels.
  card.dataset.keepout = "";
  card.setAttribute("role", "status");
  const head = el(doc, "div", "dh-debut__head");
  const mark = el(doc, "span", "dh-icon dh-debut__icon");
  const kicker = el(doc, "span", "dh-debut__kicker", "");
  const name = el(doc, "span", "dh-title dh-debut__name", "");
  const titleCol = el(doc, "div", "dh-debut__titles");
  titleCol.append(kicker, name);
  head.append(mark, titleCol);
  const does = el(doc, "div", "dh-debut__line", "");
  const counter = el(doc, "div", "dh-debut__line dh-debut__counter", "");
  card.append(head, does, counter);
  setShown(card, false);
  root.append(card);

  let world: World | null = null;
  const seen = new Set<FoeId>();
  const queue: QueuedDebut[] = [];
  let now = 0;
  let showing: FoeId | null = null;
  let until = 0;

  const show = (foe: FoeId, now: number): void => {
    const lines = DEBUT_LINES[foe];
    const general = foe in GENERALS;
    const def = general ? GENERALS[foe as keyof typeof GENERALS] : ENEMIES[foe as keyof typeof ENEMIES];
    if (!lines || !def) return;
    showing = foe;
    until = now + DEBUT_MS;
    mark.innerHTML = general ? icon("crown", { box: 28 }) : foeIcon(def.family, { box: 28 });
    setText(kicker, general ? "New general" : "New foe");
    setText(name, def.nameVi);
    setText(does, lines.does);
    // Skill keys are named the way the HUD shows them (⌥1 on a Mac).
    setText(counter, "Counter: " + lines.counter.replace("Fire Breath", "Fire Breath (" + keyLabel("skill-1") + ")").replace("Sky Fire", "Sky Fire (" + keyLabel("skill-2") + ")"));
    card.classList.toggle("is-general", general);
    card.classList.remove("is-on");
    void card.offsetWidth;
    card.classList.add("is-on");
    setShown(card, true);
    const shown = readShown();
    shown[foe] = (shown[foe] ?? 0) + 1;
    safeLocalStorage.setItem(STORE_KEY, JSON.stringify(shown));
  };

  return {
    onEvents(events: readonly SimEvent[], w: World): void {
      if (w !== world) {
        // A new run: every species may be introduced again (within SHOWN_MAX).
        world = w;
        seen.clear();
        queue.length = 0;
        showing = null;
        setShown(card, false);
      }
      for (const foe of debutsIn(events, seen, readShown())) queue.push({ foe, at: now });
    },
    frame(w: World, info: FrameInfo): void {
      now = info.now;
      if (w.phase === "victory" || w.phase === "defeat") {
        queue.length = 0;
        showing = null;
        setShown(card, false);
        return;
      }
      if (showing !== null && info.now >= until) {
        showing = null;
        setShown(card, false);
      }
      if (showing === null) {
        const next = nextDebut(queue, info.now);
        if (next !== null) show(next, info.now);
      }
    },
    dispose(): void {
      card.remove();
    },
  };
}

src/ui/hud.ts:
/**
 * In-wave HUD (05 §4.2): top-left gold, wave n/N, chain and phase;
 * top-right system buttons (pause, camera);
 * bottom-left Hỏa Long (HP, shield, armour, level), skill slots Alt + 1/2 with
 * cooldowns, the urgent-word Long Hống, consumable slots Alt + 7/8, Long Nộ and
 * Viêm Đế (Alt + 5). Bạch Long stands by as a guide (00 D21). DOM, ≤ 10 % of
 * the screen in a wave, buttons never take focus. Panels carry `data-keepout`
 * so word tags can stay clear of them.
 * Owner: ui (LANES.md).
 */
import type { ActionHandler, CommandSink, FrameInfo, Presenter } from "../app/contracts";
import { CONSUMABLES } from "../content/data/our-side";
import { CHAIN, FLOW, HERO_LEVEL, HERO_SKILLS, OUR_SIDE, RAGE, URGENT } from "../content/rules";
import type { ConsumableId, HeroSkillId, SimCommand, SimEvent } from "../content/types";
import { TICK_HZ, msToTicks } from "../sim/fixed";
import type { World } from "../sim/world";
import { el, icon, keyLabel, setClass, setShown, setText, setVar, uiButton } from "./skin";

// ── Pure read-outs (tests/ui/hud.test.ts) ───────────────────────────────────

type Clock = Pick<World, "tick" | "phaseEndsAt">;

/** Ticks left in the current phase, or null while it waits for a command (prep, Easy breaks). */
export function phaseTicksLeft(world: Clock): number | null {
  return world.phaseEndsAt < 0 ? null : Math.max(0, world.phaseEndsAt - world.tick);
}

/** Whole seconds to show on a countdown (20 at the start of a 20 s break, 1 at its end). */
export const clockSeconds = (ticks: number): number => Math.ceil(ticks / TICK_HZ);

/** Shift + Enter gold for the time left (00 §4.5): 2 per whole second, at most 40. */
export function callEarlyBonus(ticksLeft: number, room = Number.POSITIVE_INFINITY): number {
  // `room`: what the stage's 15 % "other" gold pool still holds (sim economy callEarlyRoom).
  return Math.min(FLOW.callEarlyGoldMax, FLOW.callEarlyGoldPerS * Math.floor(ticksLeft / TICK_HZ), Number.isFinite(room) ? Math.max(0, room) : Number.POSITIVE_INFINITY);
}

/** The upcoming wave in prep, warning and break: world.wave is the current or last one (0 before the first). */
export function upcomingWave(world: Pick<World, "wave" | "stage">): number {
  return Math.min(world.wave + 1, world.stage.waves.length);
}

export interface CooldownView {
  /** Seconds left, rounded up (0: ready). */
  readonly leftS: number;
  /** Share of the cooldown still to run, 0–1. */
  readonly frac: number;
}

const cooldown = (readyAt: number, tick: number, totalMs: number): CooldownView => {
  const left = Math.max(0, readyAt - tick);
  const total = Math.max(1, msToTicks(totalMs));
  return { leftS: clockSeconds(left), frac: Math.min(1, left / total) };
};

/** Hỏa Long's skills on keys (01 §2.4, 00 §6); Long Hống comes from the urgent word, Viêm Đế from full rage. */
export const SKILL_SLOTS: readonly { readonly skill: HeroSkillId; readonly action: string; readonly nameVi: string; readonly icon: string }[] = [
  { skill: "breath", action: "skill-1", nameVi: "Fire Breath", icon: "breath" },
  { skill: "skyfire", action: "skill-2", nameVi: "Sky Fire", icon: "skyfire" },
];

export const ULT_SLOT = { skill: "inferno" as HeroSkillId, action: "ult-fire", nameVi: "Inferno", icon: "inferno" };

export function skillCooldown(world: World, skill: HeroSkillId): CooldownView {
  const spec = HERO_SKILLS[skill];
  const totalMs = "cooldownMs" in spec ? spec.cooldownMs : 1;
  return cooldown(world.combat.readyAt[skill], world.tick, totalMs);
}

export interface UltView {
  /** Long Nộ 0–100 (one decimal dropped). */
  readonly rage: number;
  readonly full: boolean;
  /** Viêm Đế burning now, and its seconds left. */
  readonly active: boolean;
  readonly activeS: number;
  /** Seconds until the 45 s gap between ultimates allows another (0: free). */
  readonly gapS: number;
}

export function ultView(world: World): UltView {
  const combat = world.combat;
  const rage = Math.floor(Math.max(0, Math.min(RAGE.maxX10, combat.rage)) / 10);
  const activeLeft = Math.max(0, combat.infernoUntil - world.tick);
  const gapLeft = combat.lastUltAt < 0 ? 0 : Math.max(0, combat.lastUltAt + msToTicks(RAGE.minIntervalMs) - world.tick);
  return { rage, full: combat.rage >= RAGE.maxX10, active: activeLeft > 0, activeS: clockSeconds(activeLeft), gapS: clockSeconds(gapLeft) };
}

export interface ConsumableSlotView {
  /** 0-based slot; Alt + 7 is slot 0. */
  readonly index: number;
  readonly action: string;
  readonly item: ConsumableId | null;
  readonly count: number;
  readonly cool: CooldownView;
}

const isConsumable = (id: string): id is ConsumableId => id in CONSUMABLES;

/**
 * Consumable slots as held (03 §6.3: 2 slots, 3 each, one shared cooldown):
 * carry order first, each kind filling slots of its stack size.
 */
export function consumableSlots(world: World): ConsumableSlotView[] {
  const ids: ConsumableId[] = [];
  for (const id of [...world.stage.carry, ...Object.keys(world.shop.held)]) if (isConsumable(id) && !ids.includes(id)) ids.push(id);
  const cool = cooldown(world.shop.consumableReadyAt, world.tick, OUR_SIDE.consumableCooldownMs);
  const slots: ConsumableSlotView[] = [];
  for (const id of ids) {
    let left = world.shop.held[id] ?? 0;
    const stack = CONSUMABLES[id].stackMax;
    while (left > 0 && slots.length < OUR_SIDE.consumableSlots) {
      const count = Math.min(left, stack);
      slots.push({ index: slots.length, action: "consumable-" + (slots.length + 1), item: id, count, cool });
      left -= count;
    }
  }
  while (slots.length < OUR_SIDE.consumableSlots) slots.push({ index: slots.length, action: "consumable-" + (slots.length + 1), item: null, count: 0, cool });
  return slots;
}

/** XP progress inside the current Dragon level, 0–1 (1 at level 10). */
export function levelProgress(level: number, xp: number): number {
  const table = HERO_LEVEL.xpToLevel;
  if (level - 1 >= table.length) return 1;
  const from = level >= 2 ? table[level - 2]! : 0;
  const to = table[level - 1]!;
  return Math.max(0, Math.min(1, (xp - from) / Math.max(1, to - from)));
}

/** Chain tier 0–4 from the thresholds (00 §4.2); same rule as sim/words chainTier, kept here so the HUD loads without the sim systems. */
export function chainTierOf(chain: number): number {
  let tier = 0;
  CHAIN.thresholds.forEach((min, index) => {
    if (chain >= min) tier = index;
  });
  return tier;
}

/** M_c of the chain tier as "×1,08" (00 §4.2); empty at tier 0. */
export function chainMultiplier(chain: number): string {
  const tier = chainTierOf(chain);
  return tier === 0 ? "" : "×" + (CHAIN.mcPm[tier]! / 1000).toFixed(2);
}

/** Command-specific texts first ("command|reason"), then by reason, then by command. */
const REJECT_PAIR: Readonly<Record<string, string>> = {
  "consumable|cooldown": "Item recharging",
  "consumable|none": "No items: buy more at a break",
  "consumable|empty": "No items: buy more at a break",
  "consumable|phase": "Cannot use items now",
  "start|phase": "Stage started",
  "start|no-waves": "No waves left",
  "call-early|phase": "Call early during breaks",
  "continue|phase": "Start waves during breaks",
  "upgrade|not-ruined": "House intact: no repair needed",
  "buy|limit": "Stage purchase limit reached",
  "skill|no-target": "No target: skill unused, cooldown unchanged",
};

const REJECT_TEXT: Readonly<Record<string, string>> = {
  gold: "Need Gold",
  phase: "Only during breaks",
  cooldown: "Skill recharging",
  rage: "Dragon Rage not full",
  "ult-gap": "Ultimate: wait at least 45 s between uses",
  occupied: "Slot full",
  "slot-kind": "Item does not fit this slot",
  limit: "Limit reached",
  locked: "Item locked",
  full: "Item bag full",
  empty: "Empty slot",
  "max-level": "Max level",
  building: "Building",
  "unknown-slot": "No such slot",
  stunned: "Hỏa Long stunned",
};

const COMMAND_TEXT: Partial<Record<SimCommand["type"], string>> = {
  skill: "Cannot use skill yet",
  consumable: "Cannot use item yet",
  buy: "Cannot buy",
  place: "Cannot place",
  upgrade: "Cannot upgrade",
  sell: "Cannot sell",
  "call-early": "Cannot call early",
  start: "Cannot start",
};

/** Gentle Vietnamese text for a `rejected` event (never a red alert). */
export function rejectText(command: SimCommand["type"], reason: string): string {
  return REJECT_PAIR[command + "|" + reason] ?? REJECT_TEXT[reason] ?? COMMAND_TEXT[command] ?? "Cannot do this now";
}

// ── The HUD ─────────────────────────────────────────────────────────────────

export interface HudOptions {
  /** Pause menu (06 §2 rule 9): the pause button and the last step of Esc. */
  onPause?(): void;
  /** Camera back to the default view (Alt + 0); the button shows only when given. */
  onCameraReset?(): void;
  /** The learning panel holding the break clock (00 §4.5), or null. */
  heldBy?(): string | null;
}

export interface Hud extends Presenter, ActionHandler {
  /** Shows a short gentle message above the carry strip. */
  toast(text: string): void;
}

/** Room between the toast and the carry strip's top edge (CSS px). */
const TOAST_GAP_PX = 8;

interface SlotNodes {
  readonly button: HTMLButtonElement;
  readonly cool: HTMLElement;
  readonly time: HTMLElement;
  readonly count: HTMLElement | null;
}

export function createHud(root: HTMLElement, sink: CommandSink, options: HudOptions = {}): Hud {
  const doc = root.ownerDocument;
  const hud = el(doc, "div", "dh-hud");
  hud.dataset.ui = "hud";
  let world: World | null = null;

  const pressed = (button: HTMLElement, ok: boolean): void => {
    const name = ok ? "is-pressed" : "is-nope";
    button.classList.remove("is-pressed", "is-nope");
    void button.offsetWidth;
    button.classList.add(name);
  };

  // Top left: gold, wave, chain, phase line.
  const battle = el(doc, "section", "dh-panel dh-battle");
  battle.dataset.keepout = "";
  const goldStat = el(doc, "div", "dh-stat dh-stat--gold");
  goldStat.style.position = "relative";
  goldStat.innerHTML = `<span class="dh-icon">${icon("coin")}</span>`;
  const goldValue = el(doc, "b", "", "0");
  const goldFloat = el(doc, "span", "dh-gold-float");
  goldStat.append(goldValue, goldFloat);
  goldStat.title = "Gold";
  const waveStat = el(doc, "div", "dh-stat");
  waveStat.innerHTML = `<span class="dh-icon">${icon("wave-horn")}</span>`;
  waveStat.append(el(doc, "span", "dh-label", "Wave"));
  const waveValue = el(doc, "b", "", "0/0");
  waveStat.append(waveValue);
  const chainStat = el(doc, "div", "dh-stat dh-stat--chain");
  chainStat.innerHTML = `<span class="dh-icon">${icon("chain")}</span>`;
  chainStat.append(el(doc, "span", "dh-label", "Chain"));
  const chainValue = el(doc, "b", "", "0");
  const chainMult = el(doc, "span", "dh-chain-mult");
  chainStat.append(chainValue, chainMult);
  const phaseLine = el(doc, "div", "dh-phase");
  battle.append(goldStat, waveStat, chainStat, phaseLine);

  // Top right: system buttons.
  const system = el(doc, "div", "dh-system");
  system.dataset.keepout = "";
  const pauseButton = uiButton(doc, "dh-pause", () => options.onPause?.());
  pauseButton.innerHTML = icon("pause") + `<span class="dh-key">Esc</span>`;
  pauseButton.title = "Pause (Esc)";
  pauseButton.ariaLabel = pauseButton.title;
  setShown(pauseButton, Boolean(options.onPause));
  system.append(pauseButton);
  if (options.onCameraReset) {
    const cameraButton = uiButton(doc, "dh-camera", () => options.onCameraReset?.());
    cameraButton.innerHTML = icon("camera") + `<span class="dh-key">${keyLabel("camera-reset")}</span>`;
    cameraButton.title = "Reset camera (" + keyLabel("camera-reset") + ")";
    cameraButton.ariaLabel = cameraButton.title;
    system.prepend(cameraButton);
  }

  // Bottom left: the Dragons.
  const dragons = el(doc, "section", "dh-panel dh-dragons");
  dragons.dataset.keepout = "";
  const side = el(doc, "div");
  const portrait = el(doc, "div", "dh-portrait");
  portrait.innerHTML = icon("dragon");
  const levelBadge = el(doc, "span", "dh-level", "1");
  levelBadge.title = "Dragon level this stage";
  portrait.append(levelBadge);
  const guide = el(doc, "div", "dh-guide");
  guide.innerHTML = `<span class="dh-icon">${icon("white-dragon")}</span>`;
  guide.append(el(doc, "span", "", "Bạch Long"), el(doc, "span", "", "guide"));
  guide.title = "Bạch Long guides you from the sidelines";
  side.append(portrait, guide);

  const main = el(doc, "div", "dh-dragon-main");
  const head = el(doc, "div", "dh-dragon-head");
  head.append(el(doc, "span", "dh-title", "Hỏa Long"));
  const armourChip = el(doc, "span", "dh-chip");
  armourChip.title = "Armor";
  armourChip.innerHTML = `<span class="dh-icon">${icon("armour")}</span>`;
  const armourValue = el(doc, "b", "", "0");
  armourChip.append(armourValue);
  const shieldChip = el(doc, "span", "dh-chip");
  shieldChip.title = "Shield";
  shieldChip.innerHTML = `<span class="dh-icon">${icon("shield")}</span>`;
  const shieldValue = el(doc, "b", "", "0");
  shieldChip.append(shieldValue);
  head.append(armourChip, shieldChip);

  const hp = el(doc, "div", "dh-hp");
  const hpGhost = el(doc, "div", "dh-hp__ghost");
  const hpFill = el(doc, "div", "dh-hp__fill");
  const hpShield = el(doc, "div", "dh-hp__shield");
  const hpText = el(doc, "span", "dh-hp__text", "");
  hp.append(hpGhost, hpFill, hpShield, hpText);

  const actions = el(doc, "div", "dh-actions");
  const makeSlot = (className: string, iconName: string, keyText: string, title: string, onPress: () => void, withCount = false): SlotNodes => {
    const button = uiButton(doc, "dh-slot " + className, onPress);
    button.title = title;
    button.innerHTML = `<span class="dh-icon">${icon(iconName)}</span>`;
    const cool = el(doc, "span", "dh-slot__cool");
    const time = el(doc, "span", "dh-slot__time");
    const count = withCount ? el(doc, "span", "dh-slot__count") : null;
    const key = el(doc, "span", "dh-key", keyText);
    button.append(cool, time, key);
    if (count) button.append(count);
    return { button, cool, time, count };
  };

  const skillSlots = SKILL_SLOTS.map((slot) =>
    makeSlot("dh-skill", slot.icon, keyLabel(slot.action), slot.nameVi + " (" + keyLabel(slot.action) + ")", () => useSkill(slot.skill, slot.action)),
  );
  const roarSlot = makeSlot("dh-roar", "roar", "Urgent", "Dragon Roar: type the Urgent Word as foes close in (once per wave)", () => undefined);
  roarSlot.button.querySelector(".dh-key")?.classList.add("dh-key--word");
  const sep = el(doc, "span", "dh-actions__sep");
  const consumableNodes = Array.from({ length: OUR_SIDE.consumableSlots }, (_, index) =>
    makeSlot("dh-consumable", "potion", keyLabel("consumable-" + (index + 1)), "Item (" + keyLabel("consumable-" + (index + 1)) + ")", () => useConsumable(index), true),
  );

  const rage = el(doc, "div", "dh-rage");
  const rageLabel = el(doc, "span", "dh-label");
  rageLabel.innerHTML = icon("dragon-rage") + " Dragon Rage";
  const rageBar = el(doc, "div", "dh-rage__bar");
  const rageFill = el(doc, "div", "dh-rage__fill");
  rageBar.append(rageFill);
  const rageValue = el(doc, "span", "dh-rage__value", "0");
  const ultSlot = makeSlot("dh-ult", ULT_SLOT.icon, keyLabel(ULT_SLOT.action), ULT_SLOT.nameVi + " (" + keyLabel(ULT_SLOT.action) + "): requires full Dragon Rage", () => useSkill(ULT_SLOT.skill, ULT_SLOT.action));
  rage.append(rageLabel, rageBar, rageValue);
  actions.append(...skillSlots.map((slot) => slot.button), roarSlot.button, ultSlot.button, sep, ...consumableNodes.map((slot) => slot.button));

  main.append(head, hp, rage, actions);
  dragons.append(side, main);

  const toastNode = el(doc, "div", "dh-toast");
  toastNode.setAttribute("role", "status");
  let toastTimer = 0;
  let toastOn = false;
  /**
   * The toast stands TOAST_GAP_PX above the carry strip's top edge, as laid
   * out now: the strip folds in a wave, grows with the 11 px font floor at
   * 720p and a two-line hint, so a fixed offset put the toast over its head
   * and key hint (review 2). No strip (hidden, or a page without one): the
   * CSS offsets apply.
   */
  const placeToast = (): void => {
    const strip = root.querySelector<HTMLElement>('[data-ui="shop-strip"]');
    const box = strip !== null && strip.closest("[hidden]") === null ? strip.getBoundingClientRect() : null;
    if (box === null || box.height === 0) {
      toastNode.style.removeProperty("bottom");
      return;
    }
    toastNode.style.bottom = Math.round(hud.getBoundingClientRect().bottom - box.top + TOAST_GAP_PX) + "px";
  };
  const toast = (text: string, rejected = false): void => {
    toastNode.textContent = text;
    if (rejected) {
      const mark = el(doc, "span", "dh-icon");
      mark.innerHTML = icon("deny");
      toastNode.prepend(mark);
    }
    setClass(toastNode, "is-on", true);
    toastOn = true;
    placeToast();
    const view = doc.defaultView;
    if (!view) return;
    view.clearTimeout(toastTimer);
    toastTimer = view.setTimeout(() => {
      toastOn = false;
      setClass(toastNode, "is-on", false);
    }, 1800);
  };

  hud.append(battle, system, dragons, toastNode);
  root.append(hud);

  // Commands.
  function useSkill(skill: HeroSkillId, action: string): void {
    const node = action === ULT_SLOT.action ? ultSlot.button : skillSlots[SKILL_SLOTS.findIndex((slot) => slot.action === action)]?.button;
    if (!world || !world.stage.unlocks.heroSkills.includes(skill)) {
      if (node) pressed(node, false);
      return;
    }
    const ready = skill === "inferno" ? ultView(world).full : skillCooldown(world, skill).leftS === 0;
    if (node) pressed(node, ready);
    // The sim decides; it answers a refusal with `rejected`.
    sink({ type: "skill", skill });
  }

  function useConsumable(index: number): void {
    const node = consumableNodes[index]?.button;
    const slot = world ? consumableSlots(world)[index] : undefined;
    if (!slot || slot.item === null) {
      if (node) pressed(node, false);
      toast("Empty item slot: buy Small Potion at a break");
      return;
    }
    if (node) pressed(node, slot.cool.leftS === 0);
    sink({ type: "consumable", item: slot.item });
  }

  const frame = (w: World, _info: FrameInfo): void => {
    world = w;
    const hero = w.hero;
    const phase = w.phase;
    const total = w.stage.waves.length;
    setText(goldValue, String(w.economy.gold));
    // Prep, warning and breaks look ahead to the coming wave, like the wave card.
    const shownWave = phase === "prep" || phase === "warning" || phase === "break" ? upcomingWave(w) : Math.max(1, w.wave);
    setText(waveValue, shownWave + "/" + total);
    setText(chainValue, String(w.words.chain));
    setText(chainMult, chainMultiplier(w.words.chain));

    // The wave card owns the countdown and call-early action.
    const left = phaseTicksLeft(w);
    let line = "";
    if (phase === "prep") line = `Deploy · <b>${keyLabel("enter")}</b> to start`;
    else if (phase === "warning") line = `Wave ${upcomingWave(w)} incoming`;
    else if (phase === "break") {
      const held = options.heldBy?.() ?? null;
      line = left === null
        ? `Break · <b>${keyLabel("enter")}</b> for wave ${upcomingWave(w)}`
        : held !== null
          ? `Break · paused for ${held}`
          : "Wave break";
    } else if (phase === "wave") line = `Defending · wave <b>${w.wave}</b>`;
    else if (phase === "victory") line = "Stage cleared";
    else line = "Dragon Platform lost";
    const phaseIcon = phase === "prep" ? "phase-prep" : phase === "warning" || phase === "wave" ? "phase-fight" : phase === "break" ? "phase-break" : null;
    if (phaseIcon) line = icon(phaseIcon) + " " + line;
    if (phaseLine.innerHTML !== line) phaseLine.innerHTML = line;

    // The toast sits just above the strip, which folds outside prep and breaks (CSS fallback; placeToast measures).
    setClass(toastNode, "is-low", phase !== "prep" && phase !== "break");
    if (toastOn) placeToast();

    // Hỏa Long.
    const hpFrac = hero.hpMax > 0 ? Math.max(0, Math.min(1, hero.hp / hero.hpMax)) : 0;
    // The ghost bar trails the fill through its slower CSS transition, showing what a hit took.
    setVar(hp, "--fill", hpFrac.toFixed(4));
    setVar(hp, "--ghost", hpFrac.toFixed(4));
    const shieldFrac = hero.hpMax > 0 ? Math.min(1, hero.shield / hero.hpMax) : 0;
    setVar(hp, "--shield", shieldFrac.toFixed(4));
    setClass(hp, "is-low", hpFrac * 100 < URGENT.heroHpPct && hero.hp > 0);
    setText(hpText, hero.hp + " / " + hero.hpMax + (hero.shield > 0 ? " · shield " + hero.shield : ""));
    setText(armourValue, String(hero.armour));
    setShown(shieldChip, hero.shield > 0);
    setText(shieldValue, String(hero.shield));
    setText(levelBadge, String(hero.level));
    levelBadge.title = "Dragon level " + hero.level + " · " + Math.round(levelProgress(hero.level, hero.xp) * 100) + "% to next level";

    // Skills.
    const unlocked = w.stage.unlocks.heroSkills;
    SKILL_SLOTS.forEach((slot, index) => {
      const nodes = skillSlots[index]!;
      const open = unlocked.includes(slot.skill);
      setShown(nodes.button, open);
      if (!open) return;
      const cd = skillCooldown(w, slot.skill);
      setVar(nodes.cool, "--cool", cd.frac.toFixed(3));
      setText(nodes.time, cd.leftS > 0 ? String(cd.leftS) : "");
      setClass(nodes.button, "is-ready", cd.leftS === 0 && phase === "wave");
    });
    const roarOpen = unlocked.includes("roar") && w.stage.unlocks.urgentWord;
    setShown(roarSlot.button, roarOpen);
    setClass(roarSlot.button, "is-used", w.combat.urgentUsed);
    roarSlot.button.title = w.combat.urgentUsed ? "Dragon Roar: used this wave" : "Dragon Roar: type the Urgent Word as foes close in (once per wave)";

    // Consumables.
    const slots = consumableSlots(w);
    slots.forEach((slot, index) => {
      const nodes = consumableNodes[index]!;
      const has = slot.item !== null;
      setClass(nodes.button, "is-empty", !has);
      setVar(nodes.cool, "--cool", has ? slot.cool.frac.toFixed(3) : "0");
      setText(nodes.time, has && slot.cool.leftS > 0 ? String(slot.cool.leftS) : "");
      if (nodes.count) setText(nodes.count, has ? String(slot.count) : "");
      // Low HP in a wave and this slot can heal now: it pulses (test pass 27/10: potions stayed unused at 30 % HP).
      setClass(nodes.button, "is-hint", has && slot.cool.leftS === 0 && phase === "wave" && hpFrac * 100 < URGENT.heroHpPct && hero.hp > 0);
      const name = slot.item ? CONSUMABLES[slot.item].nameVi : "Empty";
      nodes.button.title = name + " (" + keyLabel(slot.action) + ")";
    });

    // Long Nộ and Viêm Đế.
    const ult = ultView(w);
    setShown(rage, w.stage.unlocks.rage);
    setVar(rageFill, "--fill", (ult.rage / 100).toFixed(3));
    setText(rageValue, String(ult.rage));
    setClass(rage, "is-full", ult.full);
    const ultOpen = unlocked.includes("inferno");
    setShown(ultSlot.button, ultOpen);
    setClass(ultSlot.button, "is-active", ult.active);
    setClass(ultSlot.button, "is-ready", ult.full && !ult.active && ult.gapS === 0);
    setVar(ultSlot.cool, "--cool", ult.active ? "0" : (1 - ult.rage / 100).toFixed(3));
    setText(ultSlot.time, ult.active ? String(ult.activeS) : "");
  };

  const onEvents = (events: readonly SimEvent[], w: World): void => {
    world = w;
    let goldDelta = 0;
    for (const event of events) {
      switch (event.type) {
        case "gold":
          if (event.reason !== "start") goldDelta += event.delta;
          break;
        case "rejected":
          toast(rejectText(event.command, event.reason), true);
          break;
        case "hit":
          if (event.target.kind === "hero") {
            hp.classList.remove("is-hit");
            void hp.offsetWidth;
            hp.classList.add("is-hit");
          }
          break;
        case "hero-level":
          levelBadge.classList.remove("is-up");
          void levelBadge.offsetWidth;
          levelBadge.classList.add("is-up");
          break;
        default:
          break;
      }
    }
    if (goldDelta !== 0) {
      setText(goldFloat, (goldDelta > 0 ? "+" : "−") + Math.abs(goldDelta));
      setClass(goldFloat, "is-spend", goldDelta < 0);
      goldFloat.classList.remove("is-on");
      void goldFloat.offsetWidth;
      goldFloat.classList.add("is-on");
    }
  };

  const handleAction = (action: string): boolean => {
    if (!world) return false;
    if (action === "skill-1" || action === "skill-2") {
      const slot = SKILL_SLOTS.find((entry) => entry.action === action)!;
      useSkill(slot.skill, action);
      return true;
    }
    if (action === ULT_SLOT.action) {
      useSkill(ULT_SLOT.skill, action);
      return true;
    }
    if (action.startsWith("consumable-")) {
      const index = Number(action.slice("consumable-".length)) - 1;
      if (index >= OUR_SIDE.consumableSlots) return false;
      useConsumable(index);
      return true;
    }
    if (action === "escape" && options.onPause) {
      options.onPause();
      return true;
    }
    return false;
  };

  return {
    onEvents,
    frame,
    handleAction,
    toast,
    dispose(): void {
      doc.defaultView?.clearTimeout(toastTimer);
      hud.remove();
    },
  };
}

src/ui/learning-frame.ts:
/**
 * Learning frame (01 §6.3, 05 §4.4): bottom-centre DOM queue showing word,
 * IPA and meaning by right recalls (never raw mastery, D14); new and weak
 * words pinned 2.5 s, others 0.8 s; "Vừa học" line of the last 3 new words.
 * Never shakes, never under VFX: plain DOM above the canvas, no transforms.
 *
 * Also the two learning panels: Học trước (8 new words before the stage)
 * and Thẻ Ôn (≤ 3 questions in a break), 01 §6.5. While one is open it takes
 * the letter keys (handleLetter) and Enter, Backspace, Esc, Tab.
 * Owner: typing-learning (LANES.md).
 */
import type { FrameInfo, Presenter } from "../app/contracts";
import { DIFFICULTY, LEARNING } from "../content/rules";
import type { Difficulty, SimCommand, SimEvent } from "../content/types";
import { LEARNING_FRAME_CLASSES, SEMANTIC_COLORS, installKitStyles } from "../kit/ui";
import type { World } from "../sim/world";
import { icon } from "./skin";
import { chooseSpot, keepoutRects, zonesFor, type Rect } from "./screen-zones";

/** Meaning and IPA for a word, from the loaded vocabulary. */
export type Gloss = (text: string) => { readonly vi: string; readonly ipa: string } | null;

// ── Pure rules ─────────────────────────────────────────────────────────────

/** 01 §6.3: new (no record), not yet remembered (< 2 right recalls), remembered, known (≥ 2 recalls and mastery ≥ 70). */
export type WordLevel = "new" | "unremembered" | "remembered" | "known";

export function wordLevel(word: { readonly group: string; readonly recalls: number; readonly mastery: number }): WordLevel {
  if (word.group === "new") return "new";
  if (word.recalls < LEARNING.recallsToHide) return "unremembered";
  return word.mastery < LEARNING.knownMastery ? "remembered" : "known";
}

/** A tag's meaning (01 §3.1): the first sense (cut at ";"), notes in brackets out, at most 22 characters with "…". */
export function shortMeaning(vi: string): string {
  const first = (vi.split(";")[0] ?? "").replace(/\s*\([^)]*\)/g, "").trim();
  const max = LEARNING.meaningMaxChars;
  if (first.length <= max) return first;
  // Whole senses up to the first comma that no longer fits: "yêu, thương, yêu thương" → "yêu, thương"
  // (test pass 26/10: the tag read "yêu, thương, yêu thươ…").
  const senses = first.split(",").map((part) => part.trim()).filter((part) => part !== "");
  let kept = "";
  for (const sense of senses) {
    const next = kept === "" ? sense : kept + ", " + sense;
    if (next.length > max) break;
    kept = next;
  }
  return kept !== "" ? kept : first.slice(0, max - 1).trimEnd() + "…";
}

export interface FrameWord {
  readonly text: string;
  readonly level: WordLevel;
  readonly mastery: number;
  readonly vi: string;
  readonly ipa: string;
}

export interface FrameView {
  readonly text: string;
  readonly typed: number;
  readonly ipa: string;
  readonly meaning: string;
  readonly level: WordLevel;
  /** A typed word's "word · meaning · correct" card. */
  readonly done: boolean;
}

/**
 * What the frame shows (01 §6.3): the locked word (IPA unless known; meaning
 * for new and not-yet-remembered words, or after 3 wrong keys), and after a
 * word is typed its "word · meaning correct" card: 2.5 s pinned for new and weak
 * words (nothing replaces it meanwhile), 0.8 s for others. Known words never
 * enter. Easy shows every meaning; Hard only a new word's.
 */
export class FrameQueue {
  private locked: { word: FrameWord; typed: number; hint: boolean } | null = null;
  private card: { word: FrameWord; until: number; pinned: boolean } | null = null;
  /** The last 3 new words typed, newest first ("Vừa học"). */
  readonly recent: FrameWord[] = [];

  constructor(private readonly meaning: (typeof DIFFICULTY)[Difficulty]["meaning"] = "recalls") {}

  private hidden(word: FrameWord): boolean {
    return word.level === "known" && this.meaning !== "always";
  }

  lock(word: FrameWord, typed: number, hint: boolean): void {
    this.locked = this.hidden(word) ? null : { word, typed, hint };
  }

  progress(text: string, typed: number, hint: boolean): void {
    if (this.locked && this.locked.word.text === text) Object.assign(this.locked, { typed, hint });
  }

  unlock(text?: string): void {
    if (text === undefined || this.locked?.word.text === text) this.locked = null;
  }

  /** A wave ended: the "word · meaning correct" card goes, so a Thẻ Ôn question never finds its answer pinned here. */
  clearCard(): void {
    this.card = null;
  }

  done(word: FrameWord, now: number): void {
    if (this.locked?.word.text === word.text) this.locked = null;
    if (this.hidden(word)) return;
    const pinned = word.level === "new" || word.mastery < LEARNING.weakMastery;
    if (this.card && this.card.pinned && now < this.card.until && !pinned) return;
    this.card = { word, until: now + (pinned ? LEARNING.pinNewMs : LEARNING.holdOtherMs), pinned };
    if (word.level === "new" && !this.recent.some((item) => item.text === word.text)) {
      this.recent.unshift(word);
      this.recent.length = Math.min(this.recent.length, LEARNING.recentNewWords);
    }
  }

  view(now: number): FrameView | null {
    const card = this.card && now < this.card.until ? this.card : null;
    if (card && (card.pinned || this.locked === null)) {
      return { text: card.word.text, typed: card.word.text.length, ipa: card.word.ipa, meaning: card.word.vi, level: card.word.level, done: true };
    }
    if (this.locked) {
      const { word, typed, hint } = this.locked;
      const level = word.level;
      const showMeaning = this.meaning === "always" || hint || (this.meaning === "first" ? level === "new" : level === "new" || level === "unremembered");
      return { text: word.text, typed, ipa: level === "known" ? "" : word.ipa, meaning: showMeaning ? word.vi : "", level, done: false };
    }
    return null;
  }
}

// ── Styles ─────────────────────────────────────────────────────────────────

const STYLE_ID = "dh-learning-style";
const CSS = `
.dh-learn { border: 1.5px solid rgba(255, 244, 214, 0.22); box-shadow: 0 3px 0 rgba(0, 0, 0, 0.5); transition: opacity 160ms linear; }
.dh-learn.is-idle { opacity: 0.55; }
.dh-learn.is-covered { visibility: hidden; }
.dh-learn__top { display: flex; align-items: center; gap: calc(8px * var(--ui)); }
.dh-learn__dot { width: calc(9px * var(--ui)); height: calc(9px * var(--ui)); border-radius: 50%; background: #F2B880; flex: none; }
.dh-learn__dot.is-new { background: #E9F7D4; }
.dh-learn__dot.is-remembered { background: #9FD3F2; }
.dh-learn__dot.is-known { background: #7FE08A; }
.dh-learn__speaker { width: calc(18px * var(--ui)); height: calc(18px * var(--ui)); color: var(--kit-learning-muted); flex: none; }
.dh-learn__check { color: ${SEMANTIC_COLORS.typing}; font-weight: 800; }
.dh-learn__badge { font-size: max(11px, calc(11px * var(--ui))); font-weight: 800; padding: 0 calc(5px * var(--ui)); border-radius: 3px; background: #E9F7D4; color: #1F3A12; }
.dh-learn .${LEARNING_FRAME_CLASSES.ipa}:empty, .dh-learn .${LEARNING_FRAME_CLASSES.meaning}:empty { display: none; }
.dh-learn .${LEARNING_FRAME_CLASSES.meaning} { max-width: 100%; text-align: center; }
.dh-learn .${LEARNING_FRAME_CLASSES.recent} { max-width: 100%; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; font-size: max(12px, calc(13px * var(--ui))); }
.dh-learn__idle { font-size: max(12px, calc(14px * var(--ui))); color: var(--kit-learning-muted); }
.dh-lpanel {
  position: fixed; left: 50%; top: 50%; translate: -50% -50%; z-index: 60; box-sizing: border-box;
  width: min(92vw, calc(560px * var(--ui))); padding: calc(18px * var(--ui)) calc(24px * var(--ui));
  display: grid; justify-items: center; gap: calc(8px * var(--ui)); pointer-events: auto;
  background: rgba(28, 22, 17, 0.96); color: #FFF4D6; border: 2px solid rgba(255, 244, 214, 0.25); border-radius: calc(12px * var(--ui));
  box-shadow: 0 6px 0 rgba(0, 0, 0, 0.5); font-family: var(--kit-font-battle);
}
.dh-lpanel[hidden] { display: none; }
/* Thẻ Ôn: a small card at the top centre under the next-wave card, never over the dais and its pads (05 §4.5). */
.dh-lpanel.is-card {
  top: calc(176px * var(--ui)); translate: -50% 0; width: min(92vw, calc(420px * var(--ui)));
  padding: calc(10px * var(--ui)) calc(16px * var(--ui)); gap: calc(5px * var(--ui));
}
.dh-lpanel.is-card .dh-lpanel__word { font-size: calc(28px * var(--ui)); }
.dh-lpanel.is-card .dh-lpanel__mean { font-size: max(14px, calc(17px * var(--ui))); }
.dh-lpanel.is-card .dh-lpanel__answer { min-height: calc(34px * var(--ui)); font-size: calc(26px * var(--ui)); }
.dh-lpanel__answer .x { color: #FFB4B4; text-decoration: underline wavy rgba(255, 140, 170, 0.8); }
.dh-lpanel__title { font-size: max(12px, calc(15px * var(--ui))); font-weight: 700; letter-spacing: 0.04em; color: #D9CDB0; }
.dh-lpanel__step { font-size: max(12px, calc(13px * var(--ui))); color: #B9AE95; }
.dh-lpanel__word { font-size: calc(40px * var(--ui)); font-weight: 700; }
.dh-lpanel__ipa { font-family: var(--kit-font-ipa); font-size: calc(20px * var(--ui)); color: #D9CDB0; }
.dh-lpanel__ipa:empty, .dh-lpanel__mean:empty, .dh-lpanel__word:empty { display: none; }
.dh-lpanel__mean { font-size: calc(20px * var(--ui)); text-align: center; }
.dh-lpanel__answer { min-height: calc(44px * var(--ui)); font-size: calc(32px * var(--ui)); font-weight: 700; letter-spacing: 0.12em; color: ${SEMANTIC_COLORS.typing}; }
.dh-lpanel__answer .b { color: rgba(255, 244, 214, 0.35); }
.dh-lpanel__result { min-height: calc(22px * var(--ui)); font-size: calc(17px * var(--ui)); font-weight: 700; }
.dh-lpanel__result.is-right { color: ${SEMANTIC_COLORS.typing}; }
