`;

/** Shared markup keeps completion and listening testable without a DOM. */
export function speakerMarkup(): string {
  return '<span class="dh-learn__speaker">' + icon("speaker", { box: 18 }) + '</span>';
}

export function learningWordMarkup(view: Pick<FrameView, "text" | "typed" | "done" | "level">): string {
  return '<span class="' + LEARNING_FRAME_CLASSES.typed + '">' + escapeHtml(view.text.slice(0, view.typed)) + '</span>' + escapeHtml(view.text.slice(view.typed)) +
    (view.done ? ' <span class="dh-learn__check">' + icon("check", { box: 18 }) + '</span>' : '') +
    (view.level === "new" ? ' <span class="dh-learn__badge">' + icon("new-word", { box: 18 }) + ' NEW</span>' : '');
}

export function reviewMeaningMarkup(mode: ReviewQuestion["mode"], meaning: string): string {
  return mode === "meaning" ? escapeHtml(meaning) : icon("speaker", { box: 22 });
}


function installStyles(doc: Document): void {
  installKitStyles(doc as unknown as Parameters<typeof installKitStyles>[0]);
  if (doc.getElementById(STYLE_ID) !== null) return;
  const style = doc.createElement("style");
  style.id = STYLE_ID;
  style.textContent = CSS;
  doc.head.append(style);
}

const escapeHtml = (text: string): string => text.replace(/[&<>"]/g, (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch]!);

// ── The frame ──────────────────────────────────────────────────────────────

export interface LearningFrameOptions {
  /** Plays a word (the learning client's speak); the speaker icon only shows with it. */
  readonly speak?: (text: string) => void;
}

/** The frame, and a cover for while a learning panel asks: its words and the Vừa học line would give the answers away. */
export interface LearningFramePresenter extends Presenter {
  setCovered(covered: boolean): void;
  readonly covered: boolean;
}

/** What the frame may show while a Học trước or Thẻ Ôn panel is open: nothing (01 §6.5 answers stay hidden). */
export const frameVisible = (panelOpen: boolean): boolean => !panelOpen;

export function createLearningFrame(root: HTMLElement, gloss: Gloss, options: LearningFrameOptions = {}): LearningFramePresenter {
  const doc = root.ownerDocument;
  installStyles(doc);
  const c = LEARNING_FRAME_CLASSES;
  const el = doc.createElement("div");
  el.className = c.root + " dh-learn is-idle";
  el.dataset.dhAvoid = "";
  el.setAttribute("role", "status");
  el.setAttribute("aria-live", "polite");
  el.innerHTML =
    '<div class="dh-learn__top"><i class="dh-learn__dot"></i><span class="' + c.word + '"></span>' + (options.speak ? speakerMarkup() : "") + "</div>" +
    '<div class="' + c.ipa + '"></div><div class="' + c.meaning + '"></div><div class="' + c.recent + '"></div>';
  root.append(el);
  const word = el.querySelector<HTMLElement>("." + c.word)!;
  const dot = el.querySelector<HTMLElement>(".dh-learn__dot")!;
  const ipa = el.querySelector<HTMLElement>("." + c.ipa)!;
  const meaning = el.querySelector<HTMLElement>("." + c.meaning)!;
  const recent = el.querySelector<HTMLElement>("." + c.recent)!;
  let queue: FrameQueue | null = null;
  let deckRef: unknown = null;
  const byText = new Map<string, { group: string; recalls: number; mastery: number }>();
  const slots = new Map<number, string>();
  let lockedSlot = -1;
  let key = "\u0000";
  let recentKey = "";
  let covered = false;

  const frameWord = (text: string): FrameWord => {
    const deck = byText.get(text) ?? { group: "learning", recalls: 0, mastery: 0 };
    const g = gloss(text);
    return { text, level: wordLevel(deck), mastery: deck.mastery, vi: g?.vi ?? "", ipa: g?.ipa ?? "" };
  };

  const ensure = (world: World): FrameQueue => {
    if (deckRef !== world.words.deck) {
      deckRef = world.words.deck;
      byText.clear();
      for (const item of world.words.deck.words) byText.set(item.text, item);
      queue = new FrameQueue(DIFFICULTY[world.difficulty].meaning);
    }
    return queue!;
  };

  return {
    onEvents(events: readonly SimEvent[], world: World): void {
      const q = ensure(world);
      const now = performance.now();
      for (const event of events) {
        switch (event.type) {
          case "word-assigned":
            slots.set(event.word, event.text);
            break;
          case "word-progress": {
            if (event.word < 0 || event.key === "pair") break;
            const text = slots.get(event.word);
            if (text === undefined) break;
            if (event.key === "switch" && event.typed === 0) {
              q.unlock(text);
              break;
            }
            if (event.key === "back" && event.typed === 0) {
              q.unlock(text);
              if (lockedSlot === event.word) lockedSlot = -1;
              break;
            }
            const live = world.words.live[event.word];
            const hint = live ? live.errors >= 3 : false;
            if (lockedSlot !== event.word) {
              lockedSlot = event.word;
              q.lock(frameWord(text), event.typed, hint);
            } else q.progress(text, event.typed, hint);
            break;
          }
          case "word-complete":
            q.done(frameWord(event.text), now);
            if (lockedSlot === event.word) lockedSlot = -1;
            break;
          case "word-released": {
            const text = slots.get(event.word);
            slots.delete(event.word);
            if (event.reason !== "done" && text !== undefined) q.unlock(text);
            if (lockedSlot === event.word) lockedSlot = -1;
            break;
          }
          case "wave-end":
            q.clearCard();
            break;
          default:
            break;
        }
      }
    },

    frame(world: World, info: FrameInfo): void {
      const q = ensure(world);
      const view = q.view(info.now);
      // With no word up there is nothing to lock: in a wave the frame waits quietly; prep and breaks point to the shop.
      const resting = world.phase === "prep" || world.phase === "break";
      const anyWord = world.words.live.some((item) => item !== null);
      const next = view ? [view.text, view.typed, view.ipa, view.meaning, view.level, view.done].join("|") : resting ? "rest:" + world.phase : anyWord ? "idle" : "empty";
      if (next !== key) {
        key = next;
        el.classList.toggle("is-idle", view === null);
        if (view === null) {
          word.innerHTML = resting
            ? '<span class="dh-learn__idle">' + (world.phase === "prep" ? "Deploy" : "Break") + "</span>"
            : anyWord
              ? '<span class="dh-learn__idle">Type the first letter to lock</span>'
              : "";
          ipa.textContent = meaning.textContent = "";
          dot.className = "dh-learn__dot";
        } else {
          word.innerHTML = learningWordMarkup(view);
          ipa.textContent = view.ipa;
          meaning.textContent = view.meaning;
          dot.className = "dh-learn__dot is-" + view.level;
        }
      }
      // "small (nhỏ) · big (to, lớn)": HTML collapses runs of spaces, so entries need a visible separator.
      // At 720p the line holds two words whole; the third was cut to "city (…" (test pass 26/10).
      const room = (el.ownerDocument.defaultView?.innerHeight ?? 1080) < 820 ? 2 : LEARNING.recentNewWords;
      const recentNext = q.recent.slice(0, room).map((item) => item.text + " (" + shortMeaning(item.vi) + ")").join(" · ");
      if (recentNext !== recentKey) {
        recentKey = recentNext;
        recent.textContent = recentNext === "" ? "" : "Learned: " + recentNext;
      }
    },

    setCovered(next: boolean): void {
      if (next === covered) return;
      covered = next;
      el.classList.toggle("is-covered", !frameVisible(next));
      el.setAttribute("aria-hidden", next ? "true" : "false");
    },

    get covered() {
      return covered;
    },

    dispose(): void {
      el.remove();
    },
  };
}

// ── Panels: Học trước and Thẻ Ôn (01 §6.5) ─────────────────────────────────

export interface PanelWord {
  readonly text: string;
  readonly vi: string;
  readonly ipa: string;
}

export interface PanelHooks {
  /** Plays a word now (the learning client's speak). */
  speak(text: string): void;
  /** One answer as a learning event (activity review-card, always sent). */
  recall(text: string, correct: boolean, responseMs: number, userAnswer: string): void;
  /** Player intent to the sim: learn-ahead gold, review-card answers. */
  send(command: SimCommand): void;
  /** The panel closed (the app gives keys back to the battle). */
  onClose?(): void;
  /** Wall clock, ms; default performance.now. */
  now?(): number;
  /** Delay before the next word; default setTimeout. */
  later?(ms: number, run: () => void): void;
}

/** A panel that takes the keys while open. */
export interface LearningPanel {
  readonly isOpen: boolean;
  /** A typed letter a–z; true when the panel used it. */
  handleLetter(letter: string): boolean;
  /** "enter", "backspace", "escape", "replay"; true when used. */
  handleAction(action: string): boolean;
  dispose(): void;
}

interface AnswerBox {
  readonly el: HTMLElement;
  readonly title: HTMLElement;
  readonly step: HTMLElement;
  readonly word: HTMLElement;
  readonly ipa: HTMLElement;
  readonly mean: HTMLElement;
  readonly answer: HTMLElement;
  readonly result: HTMLElement;
  readonly keys: HTMLElement;
}

function panelBox(root: HTMLElement, label: string, card = false): AnswerBox {
  const doc = root.ownerDocument;
  installStyles(doc);
  const el = doc.createElement("div");
  el.className = "dh-lpanel" + (card ? " is-card" : "");
  el.hidden = true;
  el.dataset.dhAvoid = "";
  el.setAttribute("role", "dialog");
  el.setAttribute("aria-label", label);
  el.innerHTML =
    '<div class="dh-lpanel__title"></div><div class="dh-lpanel__step"></div><div class="dh-lpanel__word"></div><div class="dh-lpanel__ipa"></div>' +
    '<div class="dh-lpanel__mean"></div><div class="dh-lpanel__answer"></div><div class="dh-lpanel__result"></div><div class="dh-lpanel__keys"></div>';
  root.append(el);
  const q = (cls: string) => el.querySelector<HTMLElement>(".dh-lpanel__" + cls)!;
  return { el, title: q("title"), step: q("step"), word: q("word"), ipa: q("ipa"), mean: q("mean"), answer: q("answer"), result: q("result"), keys: q("keys") };
}

const blanks = (typed: string, length: number): string =>
  escapeHtml(typed) + '<span class="b">' + "_".repeat(Math.max(0, length - typed.length)) + "</span>";

/** Copying a shown word (Học trước): each letter that differs from it is pink, so a slip shows at once. */
const blanksAgainst = (typed: string, target: string): string =>
  [...typed].map((ch, k) => (ch === target[k] ? escapeHtml(ch) : '<span class="x">' + escapeHtml(ch) + "</span>")).join("") +
  '<span class="b">' + "_".repeat(Math.max(0, target.length - typed.length)) + "</span>";

/** Two Esc presses within this many ms close Học trước; one skips the word on screen. */
const DOUBLE_ESC_MS = 600;

const hookNow = (hooks: PanelHooks) => (hooks.now ? hooks.now() : performance.now());
const hookLater = (hooks: PanelHooks, ms: number, run: () => void) => (hooks.later ? hooks.later(ms, run) : void setTimeout(run, ms));

/**
 * Học trước (01 §6.5): the stage's new words one by one (word, IPA, meaning,
 * sound); the player copies each once, with no time limit. A right copy goes
 * on by itself; a slip shows pink and waits for Backspace or Enter. Esc skips
 * the word on screen, Esc twice closes the panel. Closing sends learn-ahead
 * with the right answers (+5 gold each, at most +40, in the sim).
 */
export function createPrelearn(root: HTMLElement, hooks: PanelHooks): LearningPanel & { show(words: readonly PanelWord[]): void } {
  const box = panelBox(root, "Preview");
  let words: readonly PanelWord[] = [];
  let index = 0;
  let typed = "";
  let correct = 0;
  let startedAt = 0;
  let waiting = false;
  let open = false;
  let escAt = -Infinity;

  const draw = () => {
    const word = words[index]!;
    box.title.textContent = "PREVIEW · NEW STAGE WORDS";
    box.step.textContent = index + 1 + " / " + words.length;
    box.word.textContent = word.text;
    box.ipa.textContent = word.ipa;
    box.mean.textContent = word.vi;
    box.answer.innerHTML = blanksAgainst(typed, word.text);
    box.keys.textContent = "Retype · Enter submit · Tab replay · Esc skip word · Esc twice skip all";
  };
  const redraw = () => {
    const word = words[index]!;
    box.answer.innerHTML = blanksAgainst(typed, word.text);
    const slip = typed.length === word.text.length && typed !== word.text;
    box.result.textContent = slip ? "Typo: Backspace to fix, Enter to submit" : "";
    box.result.className = "dh-lpanel__result" + (slip ? " is-wrong" : "");
  };
  const finish = () => {
    open = false;
    box.el.hidden = true;
    if (correct > 0) hooks.send({ type: "learn-ahead", correct });
    hooks.onClose?.();
  };
  const next = () => {
    waiting = false;
    index += 1;
    typed = "";
    box.result.textContent = "";
    box.result.className = "dh-lpanel__result";
    if (index >= words.length) return finish();
    startedAt = hookNow(hooks);
    draw();
    hooks.speak(words[index]!.text);
  };
  const submit = () => {
    const word = words[index]!;
    const right = typed === word.text;
    if (right) correct += 1;
    hooks.recall(word.text, right, hookNow(hooks) - startedAt, typed);
    box.result.textContent = right ? "Correct! +5 Gold at stage start" : "Not quite: " + word.text;
    box.result.className = "dh-lpanel__result " + (right ? "is-right" : "is-wrong");
    waiting = true;
    hookLater(hooks, right ? 700 : 1400, next);
  };

  return {
    get isOpen() {
      return open;
    },
    show(list: readonly PanelWord[]) {
      words = list.slice(0, LEARNING.newPerStage);
      if (words.length === 0) return;
      index = 0;
      typed = "";
      correct = 0;
      open = true;
      waiting = false;
      box.el.hidden = false;
      box.result.textContent = "";
      startedAt = hookNow(hooks);
      draw();
      hooks.speak(words[0]!.text);
    },
    handleLetter(letter: string): boolean {
      if (!open) return false;
      if (waiting || !/^[a-z]$/.test(letter)) return true;
      const word = words[index]!;
      if (typed.length >= word.text.length) return true;
      typed += letter;
      // A right copy goes on at once; a slip waits for Backspace or Enter (never sent half-way by itself).
      if (typed === word.text) submit();
      else redraw();
      return true;
    },
    handleAction(action: string): boolean {
      if (!open) return false;
      if (action === "escape") {
        const now = hookNow(hooks);
        if (now - escAt <= DOUBLE_ESC_MS) finish();
        else {
          escAt = now;
          // Skips only the word on screen: no answer, no learning event for it.
          if (!waiting) next();
        }
      } else if (action === "replay") hooks.speak(words[index]!.text);
      else if (action === "backspace" && !waiting) {
        typed = typed.slice(0, -1);
        redraw();
      } else if (action === "enter" && !waiting && typed.length > 0) submit();
      return true;
    },
    dispose() {
      box.el.remove();
    },
  };
}

/** A Thẻ Ôn question: hear then type, or read the meaning then type (01 §6.5; choose-the-meaning comes from chapter 3). */
export interface ReviewQuestion extends PanelWord {
  readonly mode: "listen" | "meaning";
}

/**
 * Thẻ Ôn (01 §6.5): up to 3 questions from the wave just played. A right
 * answer sends review-card (+10 gold, +2 XP in the sim); a wrong one costs
 * nothing and shows the word, meaning and IPA again.
 * Round 2: while open it picks a spot each frame that covers no build slot,
 * no lane and no HUD panel or wave card (screen-zones.ts); without zones (UI
 * preview) it keeps the CSS spot at the top centre.
 */
export function createReviewCard(root: HTMLElement, hooks: PanelHooks): LearningPanel & { show(items: readonly ReviewQuestion[]): void } {
  const box = panelBox(root, "Review", true);
  let spot = -1;
  let placeTimer = 0;
  /** Candidate spots: top centre, top right, top left, then the sides at mid height (CSS px). */
  const place = (): void => {
    const view = root.ownerDocument.defaultView;
    const zones = zonesFor(root);
    if (!view || zones === null || box.el.hidden) return;
    const ui = Number.parseFloat(view.getComputedStyle(root.ownerDocument.documentElement).getPropertyValue("--ui")) || 1;
    const vw = view.innerWidth;
    const vh = view.innerHeight;
    const w = box.el.offsetWidth;
    const h = box.el.offsetHeight;
    const margin = 16 * ui;
    const gap = 10 * ui;
    const system = root.querySelector<HTMLElement>(".dh-system")?.getBoundingClientRect();
    const hud = root.querySelector<HTMLElement>(".dh-battle")?.getBoundingClientRect();
    const underSystem = (system && system.height > 0 ? system.bottom : 12 * ui) + gap;
    const underHud = (hud && hud.height > 0 ? hud.bottom : 12 * ui) + gap;
    const middle = Math.max(underHud, vh * 0.42 - h / 2);
    const spots: Rect[] = [
      { x: (vw - w) / 2, y: 176 * ui, w, h },
      { x: vw - margin - w, y: underSystem, w, h },
      { x: margin, y: underHud, w, h },
      { x: vw - margin - w, y: middle, w, h },
      { x: margin, y: middle, w, h },
      { x: (vw - w) / 2, y: 12 * ui, w, h },
    ];
    spot = chooseSpot(spots, zones, keepoutRects(root, box.el), { w: vw, h: vh }, spot);
    const at = spots[spot]!;
    box.el.style.left = at.x.toFixed(1) + "px";
    box.el.style.top = at.y.toFixed(1) + "px";
    box.el.style.translate = "none";
    box.el.dataset.spot = String(spot);
  };
  const follow = (): void => {
    const view = root.ownerDocument.defaultView;
    if (!view || box.el.hidden) return;
    place();
    placeTimer = view.requestAnimationFrame(follow);
  };
  let items: readonly ReviewQuestion[] = [];
  let index = 0;
  let typed = "";
  let startedAt = 0;
  let waiting = false;
  let open = false;

  const draw = () => {
    const item = items[index]!;
    box.title.textContent = "REVIEW";
    box.step.textContent = (item.mode === "listen" ? "Listen and type" : "Read the meaning, type the word") + " · " + (index + 1) + " / " + items.length;
    box.word.textContent = "";
    box.ipa.textContent = "";
    box.mean.innerHTML = reviewMeaningMarkup(item.mode, item.vi);
    box.answer.innerHTML = blanks(typed, item.text.length);
    box.result.textContent = "";
    box.result.className = "dh-lpanel__result";
    box.keys.textContent = "Enter submit · Tab replay · Esc close";
    if (item.mode === "listen") hooks.speak(item.text);
  };
  const close = () => {
    open = false;
    box.el.hidden = true;
    root.ownerDocument.defaultView?.cancelAnimationFrame(placeTimer);
    hooks.onClose?.();
  };
  const next = () => {
    waiting = false;
    index += 1;
    typed = "";
    if (index >= items.length) return close();
    startedAt = hookNow(hooks);
    draw();
  };
  const submit = () => {
    const item = items[index]!;
    const right = typed === item.text;
    hooks.recall(item.text, right, hookNow(hooks) - startedAt, typed);
    hooks.send({ type: "review-card", correct: right });
    if (right) {
      box.result.textContent = "Correct! +10 Gold";
      box.result.className = "dh-lpanel__result is-right";
    } else {
      box.word.textContent = item.text;
      box.ipa.textContent = item.ipa;
      box.mean.textContent = item.vi;
      box.result.textContent = "Not quite. Try to remember it";
      box.result.className = "dh-lpanel__result is-wrong";
      hooks.speak(item.text);
    }
    waiting = true;
    hookLater(hooks, right ? 800 : 1800, next);
  };

  return {
    get isOpen() {
      return open;
    },
    show(list: readonly ReviewQuestion[]) {
      items = list.slice(0, 3);
      if (items.length === 0) return;
      index = 0;
      typed = "";
      open = true;
      waiting = false;
      box.el.hidden = false;
      startedAt = hookNow(hooks);
      draw();
      spot = -1;
      root.ownerDocument.defaultView?.cancelAnimationFrame(placeTimer);
      follow();
    },
    handleLetter(letter: string): boolean {
      if (!open) return false;
      if (waiting || !/^[a-z]$/.test(letter)) return true;
      const item = items[index]!;
      if (typed.length >= item.text.length) return true;
      typed += letter;
      box.answer.innerHTML = blanks(typed, item.text.length);
      if (typed.length === item.text.length) submit();
      return true;
    },
    handleAction(action: string): boolean {
      if (!open) return false;
      if (action === "escape") close();
      else if (action === "replay") hooks.speak(items[index]!.text);
      else if (action === "backspace" && !waiting) {
        typed = typed.slice(0, -1);
        box.answer.innerHTML = blanks(typed, items[index]!.text.length);
      } else if (action === "enter" && !waiting && typed.length > 0) submit();
      return true;
    },
    dispose() {
      root.ownerDocument.defaultView?.cancelAnimationFrame(placeTimer);
      box.el.remove();
    },
  };
}

src/ui/placement-ui.ts:
/**
 * Placement mode (00 §6, 03 §4.2, 05 §4.5): number key picks an item and
 * lights the suggested slot; arrows move between slots; Enter places; Esc
 * cancels; Backquote edit mode with `=` upgrade and `-` sell (press twice).
 * Slots show only while placing or in prep and breaks (05 §2.1). Mouse: click
 * a lit slot to place; in a break click an empty slot for the items it takes,
 * or a built one to upgrade or sell. DOM markers and an SVG range ring follow
 * the camera through the Projector; the ground ghost goes through the view's
 * paths.showSlots (`onSlots`). Letters still type foes: this part never
 * claims them.
 * Owner: ui (LANES.md).
 */
import type { ActionHandler, CommandSink, FrameInfo, Presenter, Projector, ScreenPoint } from "../app/contracts";
import { HOUSES, TRAPS, UNITS } from "../content/data/our-side";
import { BLOCK, RINGS } from "../content/rules";
import type { MapDef, PlaceableId, SimEvent, SlotDef, SlotKind, UpgradeDef, Vec2 } from "../content/types";
import { MAX_LEVEL, canPlace as simCanPlace, sellRefund as simSellRefund, suggestedSlots as simSuggestedSlots, upgradePrice, type PlaceCheck } from "../sim/placement";
import type { World } from "../sim/world";
import { upcomingWave } from "./hud";
import { publishZones } from "./screen-zones";
import { el, icon, keyLabel, setClass, setShown, setText, uiButton } from "./skin";
import { summarizeWave } from "./wave-card";

// ── Pure helpers (tests/ui/placement.test.ts) ──────────────────────────────

export const MAX_ITEM_LEVEL = MAX_LEVEL;
/** A second `=` or `-` within this long confirms (00 §6: press twice). */
export const CONFIRM_MS = 2000;

export interface PlaceableInfo {
  readonly id: PlaceableId;
  readonly nameVi: string;
  readonly cost: number;
  readonly slot: SlotKind;
  readonly icon: string;
  readonly upgrade: UpgradeDef;
}

export function isPlaceable(id: string): id is PlaceableId {
  return id in TRAPS || id in HOUSES || id in UNITS;
}

export function placeableInfo(id: PlaceableId): PlaceableInfo {
  const def = id in TRAPS ? TRAPS[id as keyof typeof TRAPS] : id in HOUSES ? HOUSES[id as keyof typeof HOUSES] : UNITS[id as keyof typeof UNITS];
  return { id, nameVi: def.nameVi, cost: def.cost, slot: def.footprint.slot, icon: id, upgrade: def.upgrade };
}

/** Gold for the next level of an item at `level` (the sim's upgradePrice, 03 §0.2); null at the top. */
export function upgradeCost(item: PlaceableId, level: number): number | null {
  const price = upgradePrice(item, level);
  return price > 0 ? price : null;
}

/** Gold selling slot `index` gives back now (the sim's sellRefund, 03 §0.2: 70 %, 100 % in the break it was bought). */
export function sellRefund(world: World, index: number): number {
  return simSellRefund(world, index);
}

/** The Dragon's keep-out on screen: the dais rim (RINGS.daisMm) and up to Hỏa Long's head (2.5 m hover, 05 §6.1). */
const DAIS_KEEP_RADIUS_M = RINGS.daisMm / 1000;
const DAIS_KEEP_TOP_M = 7;

/** Building, upgrading and selling happen in prep and breaks (03 §0.1 rule 6; quick place from C6 is not in M0). */
export const buildPhase = (phase: World["phase"]): boolean => phase === "prep" || phase === "break";

const SLOT_KIND_VI: Readonly<Record<SlotKind, string>> = { trap: "Trap slot", house: "House pad", block: "Block point" };

const PLACE_REASON_VI: Readonly<Record<Exclude<PlaceCheck, { ok: true }>["reason"], string>> = {
  "slot-kind": "Item does not fit slot",
  occupied: "Slot full",
  phase: "Place during breaks",
  gold: "Need Gold",
  limit: "Item limit reached",
  locked: "Item locked",
  "unknown-slot": "No such slot",
};

/** Vietnamese reason a place check failed, with the gold missing when that is why; null when it is fine. */
export function placeReason(check: PlaceCheck, gold: number, cost: number): string | null {
  if (check.ok) return null;
  if (check.reason === "gold") return "Need " + Math.max(0, cost - gold) + " Gold";
  return PLACE_REASON_VI[check.reason];
}

export type Direction = "left" | "right" | "up" | "down";

const DIRS: Readonly<Record<Direction, readonly [number, number]>> = { left: [-1, 0], right: [1, 0], up: [0, -1], down: [0, 1] };

/**
 * The candidate an arrow moves to on screen: the nearest one in that
 * direction (sideways distance counts double); with none there, the next or
 * previous in keyboard order (wrapping).
 */
export function stepByDirection(
  points: ReadonlyMap<number, { readonly x: number; readonly y: number }>,
  candidates: readonly number[],
  from: number,
  dir: Direction,
): number {
  if (candidates.length === 0) return -1;
  const at = points.get(from);
  const [dx, dy] = DIRS[dir];
  if (at) {
    // First inside a cone of about ±63° around the arrow, then anything ahead.
    for (const coneOnly of [true, false]) {
      let best = -1;
      let bestCost = Infinity;
      for (const index of candidates) {
        if (index === from) continue;
        const p = points.get(index);
        if (!p) continue;
        const vx = p.x - at.x;
        const vy = p.y - at.y;
        const along = vx * dx + vy * dy;
        const side = Math.abs(vx * dy - vy * dx);
        if (along <= 1 || (coneOnly && along * 2 < side)) continue;
        const cost = along + side * 2;
        if (cost < bestCost) {
          bestCost = cost;
          best = index;
        }
      }
      if (best >= 0) return best;
    }
  }
  const k = candidates.indexOf(from);
  const forward = dir === "right" || dir === "down";
  if (k < 0) return candidates[0]!;
  return candidates[(k + (forward ? 1 : candidates.length - 1)) % candidates.length]!;
}

/** Unit direction of a lane near `pos` (metres), gate towards the dais. */
export function laneDirection(map: MapDef, laneId: string, pos: Vec2): Vec2 {
  const lane = map.lanes.find((entry) => entry.id === laneId);
  if (!lane || lane.points.length < 2) return [0, 1];
  let best: Vec2 = [0, 1];
  let bestD = Infinity;
  for (let k = 1; k < lane.points.length; k += 1) {
    const [ax, az] = lane.points[k - 1]!;
    const [bx, bz] = lane.points[k]!;
    const sx = bx - ax;
    const sz = bz - az;
    const len2 = sx * sx + sz * sz || 1;
    const t = Math.max(0, Math.min(1, ((pos[0] - ax) * sx + (pos[1] - az) * sz) / len2));
    const qx = ax + sx * t - pos[0];
    const qz = az + sz * t - pos[1];
    const d = qx * qx + qz * qz;
    if (d < bestD) {
      bestD = d;
      const len = Math.sqrt(len2);
      best = [sx / len, sz / len];
    }
  }
  return best;
}

/** The ground outline (metres) an item covers at a slot: a strip along the lane, or a circle (house aura, trap area, unit leash). */
export function areaOutline(map: MapDef, slot: SlotDef, item: PlaceableId, points = 32): Vec2[] {
  let radiusM = BLOCK.leashMm / 1000;
  if (item in TRAPS) {
    const area = TRAPS[item as keyof typeof TRAPS].area;
    if (area.shape === "strip" && slot.lane) {
      const [ux, uz] = laneDirection(map, slot.lane, slot.pos);
      const half = (area.lengthMm ?? area.radiusMm * 2) / 2000;
      const side = area.radiusMm / 1000;
      const [x, z] = slot.pos;
      return [
        [x - ux * half - uz * side, z - uz * half + ux * side],
        [x + ux * half - uz * side, z + uz * half + ux * side],
        [x + ux * half + uz * side, z + uz * half - ux * side],
        [x - ux * half + uz * side, z - uz * half - ux * side],
      ];
    }
    radiusM = area.radiusMm / 1000;
  } else if (item in HOUSES) radiusM = HOUSES[item as keyof typeof HOUSES].radiusMm / 1000;
  const out: Vec2[] = [];
  for (let k = 0; k < points; k += 1) {
    const a = (k / points) * Math.PI * 2;
    out.push([slot.pos[0] + Math.cos(a) * radiusM, slot.pos[1] + Math.sin(a) * radiusM]);
  }
  return out;
}

/** Block points sit beside the path (05 §4.5: a planted flag), so their marker moves 2.2 m to the lane's right, clear of the trap slot there. */
export const BLOCK_MARKER_SIDE_M = 2.2;

/** Where a slot's DOM marker goes (metres); trap slots and pads stay on their point. */
export function markerPoint(map: MapDef, slot: SlotDef): Vec2 {
  if (slot.kind !== "block" || !slot.lane) return slot.pos;
  const [ux, uz] = laneDirection(map, slot.lane, slot.pos);
  // Right of travel (x east, z south): (−uz, ux).
  return [slot.pos[0] - uz * BLOCK_MARKER_SIDE_M, slot.pos[1] + ux * BLOCK_MARKER_SIDE_M];
}

// ── The placement layer ─────────────────────────────────────────────────────

export type PlacementMode = "idle" | "place" | "edit";

/** Placement queries; the sim's placement.ts by default (a mock page may pass its own). */
export interface PlacementRules {
  canPlace(world: World, item: PlaceableId, index: number): PlaceCheck;
  suggestedSlots(world: World, item: PlaceableId): number[];
}

export const SIM_PLACEMENT_RULES: PlacementRules = { canPlace: simCanPlace, suggestedSlots: simSuggestedSlots };

export interface PlacementOptions {
  /** Ground slot markers in the view (paths.showSlots): visible, and the slots to light. */
  onSlots?(visible: boolean, highlight: readonly number[]): void;
  rules?: PlacementRules;
}

/** What the carry strip drives. */
export interface PlacementControl {
  readonly mode: PlacementMode;
  readonly item: PlaceableId | null;
  /** Enters placement with `item` (pressing it again moves to the next suggested slot); false outside prep and breaks. */
  begin(item: PlaceableId): boolean;
  /** Enters edit mode over built items. */
  edit(): boolean;
  cancel(): void;
}

export type PlacementUi = Presenter & ActionHandler & PlacementControl;

interface Marker {
  readonly node: HTMLButtonElement;
  iconKey: string;
}

export function createPlacementUi(root: HTMLElement, project: Projector, sink: CommandSink, options: PlacementOptions = {}): PlacementUi {
  const doc = root.ownerDocument;
  const rules = options.rules ?? SIM_PLACEMENT_RULES;
  const SVG_NS = "http://www.w3.org/2000/svg";

  const layer = el(doc, "div", "dh-place");
  layer.dataset.ui = "placement";
  const svg = doc.createElementNS(SVG_NS, "svg");
  svg.setAttribute("class", "dh-place__rings");
  const ring = doc.createElementNS(SVG_NS, "polygon");
  ring.setAttribute("class", "dh-place__ring");
  svg.append(ring);
  const markersNode = el(doc, "div");
  const card = el(doc, "div", "dh-panel dh-place-card");
  const cardTitle = el(doc, "span", "dh-title");
  const cardLines = el(doc, "div", "dh-place-card__lines");
  card.append(cardTitle, cardLines);
  const menu = el(doc, "div", "dh-panel dh-place-menu");
  const help = el(doc, "div", "dh-place-help");
  layer.append(svg, markersNode, help);
  setShown(card, false);
  setShown(menu, false);
  setShown(help, false);
  // The card and menu sit above the HUD so they never hide under a panel.
  root.append(layer, card, menu);

  let world: World | null = null;
  let mode: PlacementMode = "idle";
  let item: PlaceableId | null = null;
  let cursor = -1;
  let candidates: number[] = [];
  let armed: { action: "upgrade" | "sell"; slot: number; until: number } | null = null;
  let menuSlot = -1;
  let menuArmed: { action: "upgrade" | "sell"; until: number } | null = null;
  let notice = "";
  let noticeUntil = 0;
  let now = 0;
  let lastSlotsKey = "";
  let lastCardKey = "";
  let lastMenuKey = "";
  const markers: Marker[] = [];
  const screen = new Map<number, ScreenPoint>();
  const scratch: ScreenPoint = { x: 0, y: 0, visible: false };

  const say = (text: string): void => {
    notice = text;
    noticeUntil = now + 1800;
  };

  const slotName = (w: World, index: number): string => {
    const slot = w.slots[index];
    if (!slot) return "";
    const lane = slot.def.lane ? w.map.lanes.find((entry) => entry.id === slot.def.lane)?.nameVi : null;
    return SLOT_KIND_VI[slot.def.kind] + (lane ? " · " + lane : slot.def.ring === "outer" ? " · outer ring" : slot.def.ring === "inner" ? " · inner ring" : "");
  };

  const closeMenu = (): void => {
    menuSlot = -1;
    menuArmed = null;
    lastMenuKey = "";
    setShown(menu, false);
  };

  const cancel = (): void => {
    mode = "idle";
    item = null;
    cursor = -1;
    armed = null;
    candidates = [];
    closeMenu();
  };

  const begin = (next: PlaceableId): boolean => {
    if (!world) return false;
    if (!buildPhase(world.phase)) {
      say("Place items during breaks");
      return false;
    }
    closeMenu();
    armed = null;
    if (mode === "place" && item === next) {
      // Same key again: next suggested slot.
      const list = rules.suggestedSlots(world, next);
      if (list.length > 0) cursor = list[(list.indexOf(cursor) + 1) % list.length]!;
      return true;
    }
    mode = "place";
    item = next;
    cursor = -1;
    return true;
  };

  const edit = (): boolean => {
    if (!world) return false;
    if (!buildPhase(world.phase)) {
      say("Edit items during breaks");
      return false;
    }
    if (!world.slots.some((slot) => slot.item !== null)) {
      say("No items to edit");
      return false;
    }
    closeMenu();
    mode = "edit";
    item = null;
    armed = null;
    cursor = -1;
    return true;
  };

  const placeAt = (index: number, what: PlaceableId): void => {
    if (!world) return;
    const slot = world.slots[index];
    if (!slot) return;
    const check = rules.canPlace(world, what, index);
    const reason = placeReason(check, world.economy.gold, placeableInfo(what).cost);
    if (reason) {
      say(reason);
      return;
    }
    sink({ type: "place", item: what, slot: slot.def.id });
    cancel();
  };

  /** `=` or `-` on a built slot: the first press arms, a second within 2 s sends. */
  const pressEdit = (action: "upgrade" | "sell", index: number, viaMenu: boolean): void => {
    if (!world) return;
    const slot = world.slots[index];
    if (!slot || slot.item === null) return;
    if (action === "upgrade" && upgradeCost(slot.item, slot.level) === null) {
      say("Max level");
      return;
    }
    const current = viaMenu ? menuArmed : armed && armed.slot === index ? armed : null;
    if (current && current.action === action && now <= current.until) {
      sink(action === "upgrade" ? { type: "upgrade", slot: slot.def.id } : { type: "sell", slot: slot.def.id });
      if (viaMenu) closeMenu();
      armed = null;
      menuArmed = null;
      if (action === "sell" && mode === "edit") cursor = -1;
      return;
    }
    if (viaMenu) menuArmed = { action, until: now + CONFIRM_MS };
    else armed = { action, slot: index, until: now + CONFIRM_MS };
  };

  const openMenu = (index: number): void => {
    if (!world || !buildPhase(world.phase)) return;
    if (menuSlot === index) {
      closeMenu();
      return;
    }
    menuSlot = index;
    menuArmed = null;
    lastMenuKey = "";
  };

  const onMarker = (index: number): void => {
    if (!world) return;
    if (mode === "place" && item) {
      if (candidates.includes(index)) placeAt(index, item);
      return;
    }
    if (mode === "edit") {
      if (world.slots[index]?.item) cursor = index;
      return;
    }
    openMenu(index);
  };

  const ensureMarkers = (w: World): void => {
    while (markers.length < w.slots.length) {
      const index = markers.length;
      const node = uiButton(doc, "dh-marker", () => onMarker(index));
      node.dataset.slot = String(index);
      node.addEventListener("mouseenter", () => {
        if ((mode === "place" && candidates.includes(index)) || (mode === "edit" && world?.slots[index]?.item)) cursor = index;
      });
      node.addEventListener("contextmenu", (event) => {
        event.preventDefault();
        cancel();
      });
      node.hidden = true;
      markersNode.append(node);
      markers.push({ node, iconKey: "" });
    }
  };

  const kindIcon: Readonly<Record<SlotKind, string>> = { trap: "bar", house: "rune", block: "flag" };

  const daisPoint: ScreenPoint = { x: 0, y: 0, visible: false };
  /**
   * Hỏa Long on the dais, on screen: the box round the dais rim and the Dragon
   * hovering over it (2.5 m up, head about 7 m). A slot menu must not cover it
   * (round 2 gate: at 1080p the menu of a slot by the dais hid the Dragon).
   */
  const daisRect = (): { left: number; top: number; right: number; bottom: number } | null => {
    const r = DAIS_KEEP_RADIUS_M;
    let left = Infinity;
    let top = Infinity;
    let right = -Infinity;
    let bottom = -Infinity;
    for (const [px, pz] of [[r, 0], [-r, 0], [0, r], [0, -r]] as const) {
      for (const py of [0, DAIS_KEEP_TOP_M]) {
        project(px, py, pz, daisPoint);
        if (!Number.isFinite(daisPoint.x) || !Number.isFinite(daisPoint.y)) continue;
        left = Math.min(left, daisPoint.x);
        right = Math.max(right, daisPoint.x);
        top = Math.min(top, daisPoint.y);
        bottom = Math.max(bottom, daisPoint.y);
      }
    }
    return right > left && bottom > top ? { left, top, right, bottom } : null;
  };

  /** Puts a floating panel next to a screen point, clear of HUD panels (`data-keepout`), the Dragon and inside the viewport. */
  const placeNear = (node: HTMLElement, x: number, y: number, prefer: "above" | "below"): void => {
    const view = doc.defaultView;
    if (!view) return;
    const ui = Number.parseFloat(view.getComputedStyle(doc.documentElement).getPropertyValue("--ui")) || 1;
    const w = node.offsetWidth;
    const h = node.offsetHeight;
    const gap = 24 * ui;
    const keep = [...root.querySelectorAll<HTMLElement>("[data-keepout]")].filter((panel) => !panel.hidden && panel.offsetParent !== null).map((panel) => panel.getBoundingClientRect());
    const dais = daisRect();
    const above = { left: x - w / 2, top: y - gap - h };
    const below = { left: x - w / 2, top: y + gap };
    const toRight = { left: x + gap, top: y - h / 2 };
    const toLeft = { left: x - gap - w, top: y - h / 2 };
    // Beside the slot on the side away from the dais first, so a slot next to the Dragon opens outward.
    const outward = dais !== null && x < (dais.left + dais.right) / 2;
    const spots = prefer === "above" ? [above, below] : [below, above];
    spots.push(...(outward ? [toLeft, toRight] : [toRight, toLeft]));
    // Last resorts: a step further out on the outward side, or further down.
    spots.push({ left: outward ? toLeft.left - w / 2 : toRight.left + w / 2, top: y - h / 2 }, { left: x - w / 2, top: y + gap + h / 2 });
    const margin = 8;
    let best = spots[0]!;
    let bestCost = Infinity;
    for (const spot of spots) {
      const left = Math.max(margin, Math.min(view.innerWidth - w - margin, spot.left));
      const top = Math.max(margin, Math.min(view.innerHeight - h - margin, spot.top));
      let cost = 0;
      for (const r of keep) {
        const ox = Math.max(0, Math.min(left + w, r.right) - Math.max(left, r.left));
        const oy = Math.max(0, Math.min(top + h, r.bottom) - Math.max(top, r.top));
        cost += ox * oy;
      }
      if (dais !== null) {
        // Covering the Dragon weighs double a HUD panel.
        const ox = Math.max(0, Math.min(left + w, dais.right) - Math.max(left, dais.left));
        const oy = Math.max(0, Math.min(top + h, dais.bottom) - Math.max(top, dais.top));
        cost += 2 * ox * oy;
      }
      // Covering the slot itself is worse than a small overlap.
      if (x > left && x < left + w && y > top && y < top + h) cost += w * h;
      if (cost < bestCost) {
        bestCost = cost;
        best = { left, top };
      }
      if (cost === 0) break;
    }
    node.style.translate = `${best.left.toFixed(1)}px ${best.top.toFixed(1)}px`;
  };

  const renderMenu = (w: World): void => {
    if (menuSlot < 0) return;
    const slot = w.slots[menuSlot];
    const at = screen.get(menuSlot);
    if (!slot || !at || !buildPhase(w.phase)) {
      closeMenu();
      return;
    }
    const key = [menuSlot, slot.item, slot.level, w.economy.gold, menuArmed?.action ?? "", w.phase].join("|");
    if (key === lastMenuKey) {
      placeNear(menu, at.x, at.y, "below");
      return;
    }
    lastMenuKey = key;
    const children: HTMLElement[] = [];
    if (slot.item === null) {
      children.push(el(doc, "span", "dh-title", slotName(w, menuSlot)));
      const items = w.stage.carry.filter((id): id is PlaceableId => isPlaceable(id) && placeableInfo(id).slot === slot.def.kind);
      for (const id of items) {
        const info = placeableInfo(id);
        const check = rules.canPlace(w, id, menuSlot);
        const reason = placeReason(check, w.economy.gold, info.cost);
        const button = uiButton(doc, reason ? "is-poor" : "", () => placeAt(menuSlot, id));
        button.title = reason ?? info.nameVi;
        const keyIndex = w.stage.carry.indexOf(id) + 1;
        button.innerHTML = `<span class="dh-key">${keyIndex}</span><span class="dh-icon">${icon(info.icon)}</span>`;
        button.append(el(doc, "span", "", info.nameVi), el(doc, "span", "", String(info.cost)));
        children.push(button);
      }
      if (items.length === 0) children.push(el(doc, "span", "dh-place-card__line", "No loadout item fits this slot"));
    } else {
      const info = placeableInfo(slot.item);
      children.push(el(doc, "span", "dh-title", info.nameVi + " · Lv. " + slot.level));
      const cost = upgradeCost(slot.item, slot.level);
      const short = cost !== null && cost > w.economy.gold ? cost - w.economy.gold : 0;
      const up = uiButton(doc, cost === null || short > 0 ? "is-poor" + (short > 0 ? " is-short" : "") : "", () => pressEdit("upgrade", menuSlot, true));
      up.innerHTML = `<span class="dh-key">=</span><span class="dh-icon">${icon("upgrade")}</span>`;
      // Short of gold: the whole row dims and says by how much, like the carry strip (test pass 27/10).
      const upLabel = menuArmed?.action === "upgrade" ? "Press again to upgrade" : cost === null ? "Max level" : "Upgrade " + (slot.level + 1) + (short > 0 ? " · need " + short + " Gold" : "");
      up.append(el(doc, "span", "", upLabel), el(doc, "span", "", cost === null ? "" : String(cost)));
      if (cost === null) up.disabled = true;
      const sell = uiButton(doc, "", () => pressEdit("sell", menuSlot, true));
      sell.innerHTML = `<span class="dh-key">-</span><span class="dh-icon">${icon("sell")}</span>`;
      sell.append(el(doc, "span", "", menuArmed?.action === "sell" ? "Press again to sell" : "Sell"), el(doc, "span", "", "+" + sellRefund(w, menuSlot)));
      children.push(up, sell);
    }
    menu.replaceChildren(...children);
    setShown(menu, true);
    placeNear(menu, at.x, at.y, "below");
  };

  const frame = (w: World, info: FrameInfo): void => {
    world = w;
    now = info.now;
    ensureMarkers(w);
    // Lanes and slots on screen, for the floating cards that must not cover them (wave card, Thẻ Ôn).
    publishZones(root, w.map, project);
    const building = buildPhase(w.phase);
    if (mode !== "idle" && !building) cancel();
    if (menuSlot >= 0 && !building) closeMenu();
    if (armed && now > armed.until) armed = null;
    if (menuArmed && now > menuArmed.until) {
      menuArmed = null;
      lastMenuKey = "";
    }

    // Which slots show (05 §2.1: only while placing or in prep and breaks).
    let visible: number[] = [];
    if (mode === "place" && item) {
      candidates = rules.suggestedSlots(w, item);
      if (!candidates.includes(cursor)) cursor = candidates[0] ?? -1;
      visible = candidates;
    } else if (mode === "edit") {
      candidates = w.slots.filter((slot) => slot.item !== null).map((slot) => slot.index);
      if (candidates.length === 0) {
        cancel();
      } else if (!candidates.includes(cursor)) cursor = candidates[0]!;
      visible = candidates;
    } else if (building) {
      visible = w.slots.map((slot) => slot.index);
    }
    const shown = new Set(visible);

    screen.clear();
    for (const marker of markers) {
      const index = Number(marker.node.dataset.slot);
      const slot = w.slots[index];
      if (!slot || !shown.has(index)) {
        setShown(marker.node, false);
        continue;
      }
      const [mx, mz] = markerPoint(w.map, slot.def);
      const p = project(mx, 0, mz, scratch);
      if (!p.visible) {
        setShown(marker.node, false);
        continue;
      }
      screen.set(index, { x: p.x, y: p.y, visible: true });
      setShown(marker.node, true);
      // The translate property, not transform: the cursor and dim scales must not scale the position.
      marker.node.style.translate = `${p.x.toFixed(1)}px ${p.y.toFixed(1)}px`;
      marker.node.dataset.kind = slot.def.kind;
      const iconKey = slot.item ? slot.item + ":" + slot.level : "empty:" + slot.def.kind;
      if (iconKey !== marker.iconKey) {
        marker.iconKey = iconKey;
        marker.node.innerHTML = slot.item
          ? `<span class="dh-icon">${icon(slot.item)}</span><span class="dh-marker__pips">${[1, 2, 3].map((k) => `<i class="${k <= slot.level ? "is-on" : ""}"></i>`).join("")}</span>`
          : `<span class="dh-icon">${icon(kindIcon[slot.def.kind])}</span>`;
        marker.node.title = slot.item ? placeableInfo(slot.item).nameVi + " · Lv. " + slot.level : slotName(w, index);
      }
      setClass(marker.node, "is-filled", slot.item !== null);
      setClass(marker.node, "is-cand", mode === "place");
      setClass(marker.node, "is-cursor", mode !== "idle" && index === cursor);
      setClass(marker.node, "is-dim", mode === "idle" && slot.item === null && menuSlot !== index);
    }

    // Range ring and the card at the cursor.
    const cursorSlot = cursor >= 0 ? w.slots[cursor] : undefined;
    const cursorAt = cursor >= 0 ? screen.get(cursor) : undefined;
    const ringItem = mode === "place" ? item : mode === "edit" ? cursorSlot?.item ?? null : null;
    if (cursorSlot && cursorAt && ringItem) {
      const outline = areaOutline(w.map, cursorSlot.def, ringItem);
      const pts: string[] = [];
      for (const [x, z] of outline) {
        const p = project(x, 0, z, scratch);
        pts.push(p.x.toFixed(1) + "," + p.y.toFixed(1));
      }
      ring.setAttribute("points", pts.join(" "));
      ring.setAttribute("class", "dh-place__ring" + (mode === "edit" ? " is-edit" : ""));
      svg.style.display = "";
    } else {
      svg.style.display = "none";
    }

    if (cursorSlot && cursorAt && mode !== "idle") {
      const lines: { html: string; armed?: boolean }[] = [];
      let titleText = "";
      if (mode === "place" && item) {
        const info = placeableInfo(item);
        titleText = info.nameVi;
        const reason = placeReason(rules.canPlace(w, item, cursor), w.economy.gold, info.cost);
        lines.push({ html: `<span class="dh-money">${info.cost} Gold</span> · ${slotName(w, cursor)}` });
        if (cursorSlot.def.lane) {
          const summary = summarizeWave(w.stage, w.map, upcomingWave(w));
          const count = summary?.lanes.find((lane) => lane.id === cursorSlot.def.lane)?.count ?? 0;
          lines.push({ html: `Next wave: <b>${count}</b> foes on this lane` });
        }
        lines.push({ html: reason ? `<b>${reason}</b>` : `<span class="dh-key">${keyLabel("enter")}</span> place · <span class="dh-key">Esc</span> cancel` });
      } else if (mode === "edit" && cursorSlot.item) {
        const info = placeableInfo(cursorSlot.item);
        titleText = info.nameVi + " · Lv. " + cursorSlot.level;
        const cost = upgradeCost(cursorSlot.item, cursorSlot.level);
        const lack = cost !== null && cost > w.economy.gold ? cost - w.economy.gold : 0;
        lines.push({
          html: cost === null ? "Max level" : `<span class="dh-key">=</span> upgrade ${cursorSlot.level + 1}: <span class="dh-money">${cost} Gold</span>` + (lack > 0 ? ` · <b>need ${lack} Gold</b>` : ""),
        });
        lines.push({ html: `<span class="dh-key">-</span> sell: <span class="dh-money">+${sellRefund(w, cursor)} Gold</span>` });
        if (armed && armed.slot === cursor) {
          const up = armed.action === "upgrade";
          lines.push({ html: `Press <span class="dh-key">${up ? "=" : "-"}</span> again to ${up ? "upgrade" : "sell"}`, armed: true });
        }
      }
      const cardKey = titleText + "|" + lines.map((line) => line.html).join("|");
      if (cardKey !== lastCardKey) {
        lastCardKey = cardKey;
        setText(cardTitle, titleText);
        cardLines.innerHTML = lines.map((line) => `<div class="dh-place-card__line${line.armed ? " is-armed" : ""}">${line.html}</div>`).join("");
      }
      setShown(card, true);
      placeNear(card, cursorAt.x, cursorAt.y, "above");
    } else {
      setShown(card, false);
    }

    renderMenu(w);

    // Help line: the keys of the current mode, or a short notice.
    let helpHtml = "";
    if (now < noticeUntil) helpHtml = notice;
    else if (mode === "place") helpHtml = candidates.length === 0 ? "No free slot for this item · <span class=\"dh-key\">Esc</span> cancel" : `<span class="dh-key">←</span><span class="dh-key">→</span><span class="dh-key">↑</span><span class="dh-key">↓</span> move · <span class="dh-key">${keyLabel("enter")}</span> place · <span class="dh-key">Esc</span> cancel · letters still target foes`;
    else if (mode === "edit") helpHtml = `Edit: <span class="dh-key">←</span><span class="dh-key">→</span> pick · <span class="dh-key">=</span> upgrade (twice) · <span class="dh-key">-</span> sell (twice) · <span class="dh-key">Esc</span> exit`;
    if (help.innerHTML !== helpHtml) help.innerHTML = helpHtml;
    setShown(help, helpHtml !== "");

    // While placing or editing, the wave card folds (CSS) so slots near the gates stay visible.
    const placing = mode === "idle" ? "" : mode;
    if (root.dataset.placing !== placing) root.dataset.placing = placing;

    // Ground markers in the view.
    const highlight = mode === "idle" ? [] : visible;
    const slotsKey = (visible.length > 0 ? "1" : "0") + ":" + highlight.join(",");
    if (slotsKey !== lastSlotsKey) {
      lastSlotsKey = slotsKey;
      options.onSlots?.(visible.length > 0, highlight);
    }
  };

  const onEvents = (events: readonly SimEvent[], w: World): void => {
    world = w;
    for (const event of events) {
      if (event.type === "phase" && !buildPhase(event.phase)) cancel();
      if (event.type === "sold" && mode === "edit" && w.slots[event.slot]) cursor = -1;
    }
  };

  const move = (dir: Direction): void => {
    if (candidates.length === 0) return;
    cursor = stepByDirection(screen, candidates, cursor, dir);
    armed = null;
  };

  const handleAction = (action: string): boolean => {
    if (!world) return false;
    const carry = /^carry-(\d)$/.exec(action);
    if (carry) {
      const id = world.stage.carry[Number(carry[1]) - 1];
      if (!id || !isPlaceable(id)) return false;
      begin(id);
      return true;
    }
    switch (action) {
      case "edit-mode":
        if (mode === "edit") cancel();
        else edit();
        return true;
      case "rotate-left":
      case "rotate-right":
      case "tilt-up":
      case "tilt-down":
        if (mode === "idle") return false;
        move(action === "rotate-left" ? "left" : action === "rotate-right" ? "right" : action === "tilt-up" ? "up" : "down");
        return true;
      case "enter":
        if (mode === "place" && item) {
          if (cursor >= 0) placeAt(cursor, item);
          else say("No free slot for this item");
          return true;
        }
        return mode === "edit";
      case "escape":
        if (menuSlot >= 0) {
          closeMenu();
          return true;
        }
        if (mode !== "idle") {
          cancel();
          return true;
        }
        return false;
      case "upgrade":
      case "sell":
        if (mode !== "edit") return false;
        if (cursor >= 0) pressEdit(action, cursor, false);
        return true;
      default:
        return false;
    }
  };

  return {
    get mode() {
      return mode;
    },
    get item() {
      return item;
    },
    begin,
    edit,
    cancel,
    onEvents,
    frame,
    handleAction,
    dispose(): void {
      options.onSlots?.(false, []);
      delete root.dataset.placing;
      layer.remove();
      card.remove();
      menu.remove();
    },
  };
}

src/ui/results.ts:
/**
 * End of the run (01 §5, §6.5; 06 §4 screens 8 and 9): victory with stars or
 * defeat, gold, accuracy, new words learned, and the Sổ Từ Ải list (words
 * met: new, mistyped, to review; listen to each). Collects the word log from
 * word events during the run. Keyboard: ↑ ↓ pick a word, Tab listens, ← →
 * pick retry or portal, Enter activates it; while shown it takes every command key.
 * Owner: ui (LANES.md).
 */
import type { ActionHandler, FrameInfo, Presenter } from "../app/contracts";
import { portalHome } from "../app/portal";
import { STARS } from "../content/rules";
import type { Grade, SimEvent, WordGroup, WordKind } from "../content/types";
import type { World } from "../sim/world";
import type { Gloss } from "./learning-frame";
import { el, icon, keyLabel, setClass, setShown, setText, uiButton } from "./skin";

export interface ResultsActions {
  retry(): void;
  /**
   * 00 §4.10: after two defeats in a row on a stage the screen offers one
   * level easier, never forcing it. Returns the easier level's name, or null
   * when there is no offer now (already Dễ, or not two defeats yet).
   */
  easierOffer?(): string | null;
  /** Replays the stage one level easier (⇧↵ on the screen). */
  easier?(): void;
  /** Says a word (kit/speech); the listen buttons show only when given. */
  listen?(text: string): void;
  /** Meaning and IPA for the list (the app's LearningClient.gloss). */
  gloss?: Gloss;
}

// ── Word log (tests/ui/results.test.ts) ─────────────────────────────────────

const GRADE_ORDER: readonly Grade[] = ["sloppy", "ok", "good", "perfect", "flash"];

export interface WordRecord {
  readonly text: string;
  group: WordGroup;
  kind: WordKind;
  /** Times it was dealt and finished. */
  met: number;
  done: number;
  /** Wrong keys over all finishes; finishes with Ẩu; finishes with a hint. */
  errors: number;
  sloppy: number;
  hints: number;
  /** Finishes with no wrong key. */
  clean: number;
  best: Grade | null;
}

export type WordStatus = "new" | "fresh" | "miss" | "review" | "good";

/**
 * Status in Sổ Từ Ải (01 §6.5: mới học, gõ sai, cần ôn). A new word is "mới
 * học" only once it was typed with no wrong key (the summary's "Từ mới đã
 * học" counts the same); a new word met but never typed clean is "fresh"
 * (test pass 27/10: the defeat screen called words never typed "Mới học").
 */
export function wordStatus(record: WordRecord): WordStatus {
  if (record.group === "new" && record.clean > 0) return "new";
  if (record.errors > 0) return "miss";
  if (record.group === "new") return "fresh";
  if (record.sloppy > 0 || record.hints > 0 || record.done === 0) return "review";
  return "good";
}

const STATUS_RANK: Readonly<Record<WordStatus, number>> = { new: 0, fresh: 1, miss: 2, review: 3, good: 4 };

/** Every word dealt in the run, from `word-assigned` and `word-complete`. */
export class WordLog {
  private readonly bySlot = new Map<number, { text: string; group: WordGroup; kind: WordKind }>();
  readonly words = new Map<string, WordRecord>();

  reset(): void {
    this.bySlot.clear();
    this.words.clear();
  }

  private record(text: string, group: WordGroup, kind: WordKind): WordRecord {
    let entry = this.words.get(text);
    if (!entry) {
      entry = { text, group, kind, met: 0, done: 0, errors: 0, sloppy: 0, hints: 0, clean: 0, best: null };
      this.words.set(text, entry);
    }
    return entry;
  }

  onEvents(events: readonly SimEvent[]): void {
    for (const event of events) {
      if (event.type === "word-assigned") {
        this.bySlot.set(event.word, { text: event.text, group: event.group, kind: event.kind });
        this.record(event.text, event.group, event.kind).met += 1;
      } else if (event.type === "word-complete") {
        const slot = this.bySlot.get(event.word);
        const entry = this.record(event.text, slot?.group ?? "known", event.kind);
        entry.done += 1;
        entry.errors += event.errors;
        if (event.errors === 0) entry.clean += 1;
        if (event.grade === "sloppy") entry.sloppy += 1;
        if (event.hintUsed) entry.hints += 1;
        if (entry.best === null || GRADE_ORDER.indexOf(event.grade) > GRADE_ORDER.indexOf(entry.best)) entry.best = event.grade;
      }
    }
  }

  /** Sổ Từ Ải order: new, mistyped, to review, then the rest; alphabetical inside. */
  list(): WordRecord[] {
    return [...this.words.values()].sort((a, b) => STATUS_RANK[wordStatus(a)] - STATUS_RANK[wordStatus(b)] || a.text.localeCompare(b.text, "en"));
  }
}

export interface ResultsSummary {
  readonly outcome: "victory" | "defeat";
  readonly stars: 0 | 1 | 2 | 3;
  /** Wave reached (the losing wave on defeat) and the stage's count. */
  readonly wave: number;
  readonly waves: number;
  readonly hpPct: number;
  readonly goldLeft: number;
  readonly goldEarned: number;
  /** Right keys over all letter keys, %; null without keys. */
  readonly accuracyPct: number | null;
  readonly words: number;
  readonly met: number;
  /** New words typed at least once with no wrong key, of the new words met. */
  readonly newLearned: number;
  readonly newMet: number;
  readonly mistyped: number;
  /** Letter keys typed in the run. */
  readonly keys: number;
  /** HP the Fire Dragon lost to Héo lan's seep and to foes' blows (the defeat line names the bigger one). */
  readonly hurt: HurtTally;
}

/** HP lost by cause, read from `hit` events on the Fire Dragon: Héo lan comes from the hero itself (combat stepBlight). */
export interface HurtTally {
  blight: number;
  blows: number;
}

export const emptyHurt = (): HurtTally => ({ blight: 0, blows: 0 });

/** Adds the Fire Dragon's losses in `events` to `tally`. */
export function tallyHurt(tally: HurtTally, events: readonly SimEvent[]): void {
  for (const event of events) {
    if (event.type !== "hit" || event.target.kind !== "hero" || event.amount <= 0) continue;
    if (event.source.kind === "hero") tally.blight += event.amount;
    else tally.blows += event.amount;
  }
}

export function summarizeRun(world: World, log: WordLog, outcome: "victory" | "defeat", stars: 0 | 1 | 2 | 3, wave: number, hurt: HurtTally = emptyHurt()): ResultsSummary {
  const records = [...log.words.values()];
  const fresh = records.filter((record) => record.group === "new");
  const keys = world.stats.keys;
  return {
    outcome,
    stars: outcome === "victory" ? stars : 0,
    wave,
    waves: world.stage.waves.length,
    hpPct: world.hero.hpMax > 0 ? Math.round((Math.max(0, world.hero.hp) * 100) / world.hero.hpMax) : 0,
    goldLeft: world.economy.gold,
    goldEarned: world.stats.goldEarned,
    accuracyPct: keys > 0 ? Math.round((Math.max(0, keys - world.stats.wrongKeys) * 100) / keys) : null,
    words: world.stats.words,
    met: records.length,
    newLearned: fresh.filter((record) => record.clean > 0).length,
    newMet: fresh.length,
    mistyped: records.filter((record) => record.errors > 0).length,
    keys,
    hurt: { ...hurt },
  };
}

/** Fewer letter keys than this in a lost run: the player hardly typed. */
const FEW_KEYS = 10;

/**
 * Why the run was lost, for the line under the title: hardly any typing, Héo
 * lan (words left waiting in the word zone), or foes' blows at the dais.
 * Test pass 27/10: the screen always advised blockers and traps, while
 * 99 % of the Dragon's losses in waves 5–10 were Héo lan and a run with no
 * key at all got the same advice.
 */
export function defeatCause(summary: Pick<ResultsSummary, "keys" | "hurt">): "typing" | "blight" | "blows" {
  if (summary.keys < FEW_KEYS) return "typing";
  return summary.hurt.blight >= summary.hurt.blows ? "blight" : "blows";
}

/** The line under the stars (06 §6: "Giữ máu Hỏa Long để có 3 sao"). */
export function starHint(summary: ResultsSummary): string {
  if (summary.outcome === "defeat") {
    const at = "Hỏa Long fell on wave " + summary.wave;
    const cause = defeatCause(summary);
    if (cause === "typing") return at + ". Type foes' words to make Hỏa Long breathe fire at them.";
    if (cause === "blight")
      return at + ", mainly from Blight: untyped foes in the Word Zone drain Hỏa Long's HP. Type foes nearest the platform first; use " + keyLabel("skill-1") + " Fire Breath when foes crowd in.";
    return at + " as foes reached the platform. Place blockers and traps on busier lanes.";
  }
  if (summary.stars >= 3) return "Hỏa Long has " + summary.hpPct + "% HP: all three stars.";
  const need = summary.stars === 2 ? STARS.threeStarHpPct : STARS.twoStarHpPct;
  return "Hỏa Long has " + summary.hpPct + "% HP. Keep at least " + need + "% for " + (summary.stars + 1) + " stars.";
}

// ── The screen ──────────────────────────────────────────────────────────────

const STATUS_VI: Readonly<Record<WordStatus, string>> = { new: "Learned", fresh: "New", miss: "Mistyped", review: "Review", good: "Good" };

/**
 * A won stage holds this long before the panel (05 §6.1 Victory, §6.7 C1):
 * the Dragon's victory clip, the camera's slow turn and the title over the
 * dais come first; Enter or Esc shows the panel at once. Test pass 27/10:
 * the panel covered the dais 0.7 s after the last word.
 */
export const VICTORY_HOLD_MS = 2600;

export function createResults(root: HTMLElement, actions: ResultsActions): Presenter & ActionHandler {
  const doc = root.ownerDocument;
  const log = new WordLog();
  let hurt = emptyHurt();
  let world: World | null = null;
  let summary: ResultsSummary | null = null;
  let list: WordRecord[] = [];
  let selected = 0;

  const screen = el(doc, "div", "dh-results");
  screen.dataset.ui = "results";
  const panel = el(doc, "section", "dh-panel dh-results__panel");
  const titleBox = el(doc, "div", "dh-results__title");
  const title = el(doc, "div", "dh-title");
  const sub = el(doc, "div", "dh-results__sub");
  titleBox.append(title, sub);
  const starsBox = el(doc, "div");
  const stars = el(doc, "div", "dh-stars");
  const starNodes = [0, 1, 2].map(() => {
    const node = el(doc, "span", "dh-star");
    node.innerHTML = icon("star-unlit", { box: 46 });
    stars.append(node);
    return node;
  });
  const hint = el(doc, "div", "dh-results__hint");
  starsBox.append(stars, hint);
  const tiles = el(doc, "div", "dh-tiles");
  const book = el(doc, "div", "dh-book");
  const bookHead = el(doc, "div", "dh-book__head");
  const bookCount = el(doc, "span");
  bookHead.append(el(doc, "span", "dh-title", "Wordbook"), bookCount);
  const bookList = el(doc, "ul", "dh-book__list");
  book.append(bookHead, bookList);
  const foot = el(doc, "div", "dh-results__foot");
  const buttons = el(doc, "div", "dh-results__actions");
  const retryButton = uiButton(doc, "dh-retry", () => actions.retry());
  // Keep focus in the window key router, as uiButton does elsewhere.
  const resultButtons: HTMLElement[] = [retryButton];
  const home = portalHome(import.meta.env.VITE_PORTAL_URL);
  if (home) {
    const portalButton = el(doc, "a", "dh-btn dh-results__portal");
    portalButton.href = home;
    portalButton.target = "_top";
    portalButton.tabIndex = -1;
    portalButton.addEventListener("mousedown", (event) => event.preventDefault());
    portalButton.innerHTML = `<span class="dh-key">${keyLabel("enter")}</span>Back to portal`;
    resultButtons.push(portalButton);
  }
  let focusedAction = 0;
  const focusAction = (index: number): void => {
    focusedAction = index;
    resultButtons.forEach((button, k) => setClass(button, "is-focused", k === index));
  };
  resultButtons.forEach((button, index) => {
    button.addEventListener("mouseenter", () => focusAction(index));
    button.addEventListener("focus", () => focusAction(index));
  });
  buttons.append(...resultButtons);
  const easierButton = uiButton(doc, "dh-retry dh-retry--easier", () => actions.easier?.());
  setShown(easierButton, false);
  const keys = el(doc, "span", "dh-results__keys");
  foot.append(buttons, easierButton, keys);
  panel.append(titleBox, starsBox, tiles, book, foot);
  screen.append(panel);
  setShown(screen, false);
  root.append(screen);
  // The title over the field while a won stage holds (VICTORY_HOLD_MS).
  const cheer = el(doc, "div", "dh-victory");
  cheer.dataset.ui = "victory";
  const cheerTitle = el(doc, "div", "dh-victory__title", "Stage cleared");
  const cheerKeys = el(doc, "div", "dh-victory__keys");
  cheerKeys.innerHTML = `<span class="dh-key">${keyLabel("enter")}</span> see results`;
  cheer.append(cheerTitle, cheerKeys);
  setShown(cheer, false);
  root.append(cheer);
  /** The defeat screen offers one level easier (⇧↵). */
  let offerEasier = false;
  /** A won stage waiting for its panel: stars, wave, and when (−1: set at the next frame). */
  let pending: { stars: 0 | 1 | 2 | 3; wave: number; at: number } | null = null;

  const tile = (value: string, label: string, artName: string, money = false): HTMLElement => {
    const node = el(doc, "div", "dh-tile" + (money ? " is-money" : ""));
    node.innerHTML = icon(artName, { box: 25 });
    node.append(el(doc, "b", "", value), el(doc, "span", "", label));
    return node;
  };

  const select = (index: number): void => {
    if (list.length === 0) return;
    selected = Math.max(0, Math.min(list.length - 1, index));
    const rows = bookList.children;
    for (let k = 0; k < rows.length; k += 1) setClass(rows[k]!, "is-sel", k === selected);
    (rows[selected] as HTMLElement | undefined)?.scrollIntoView({ block: "nearest" });
  };

  const show = (outcome: "victory" | "defeat", starCount: 0 | 1 | 2 | 3, wave: number): void => {
    if (!world) return;
    summary = summarizeRun(world, log, outcome, starCount, wave, hurt);
    const s = summary;
    setText(title, s.outcome === "victory" ? "Stage cleared" : "Dragon Platform lost");
    setText(sub, world.stage.nameVi + " · " + (s.outcome === "victory" ? s.waves + "/" + s.waves + " waves" : "lost at wave " + s.wave + "/" + s.waves));
    starNodes.forEach((node, index) => {
      setClass(node, "is-on", index < s.stars);
      node.innerHTML = icon(index < s.stars ? "star-lit" : "star-unlit", { box: 46 });
    });
    setShown(stars, s.outcome === "victory");
    setText(hint, starHint(s));
    tiles.replaceChildren(
      tile(String(s.goldLeft), "Gold left", "gold", true),
      tile(String(s.goldEarned), "Gold earned", "gold", true),
      tile(s.accuracyPct === null ? "—" : s.accuracyPct + "%", "Accuracy", "stat-accuracy"),
      tile(s.newLearned + "/" + s.newMet, "New learned", "stat-new-words"),
      tile(String(s.met), "Words seen", "stat-words-seen"),
    );
    list = log.list();
    setText(bookCount, list.length + " words · " + s.mistyped + " mistyped");
    bookList.replaceChildren(
      ...list.map((record, index) => {
        const row = el(doc, "li", "dh-word");
        const status = wordStatus(record);
        const g = actions.gloss?.(record.text) ?? null;
        const badge = el(doc, "span", "dh-wstatus is-" + status);
        const statusIcon = status === "new" ? "status-learned" : status === "fresh" ? "status-new" : status === "review" ? "status-review" : status === "good" ? "check" : null;
        badge.innerHTML = statusIcon ? icon(statusIcon, { box: 25 }) : "";
        badge.append(STATUS_VI[status] + (record.errors > 0 ? " · " + record.errors + " errors" : ""));
        row.append(
          el(doc, "span", "dh-word__text", record.text),
          el(doc, "span", "dh-word__ipa", g?.ipa ?? ""),
          el(doc, "span", "dh-word__vi", g?.vi ?? ""),
          badge,
        );
        if (actions.listen) {
          const listen = uiButton(doc, "dh-listen", () => {
            select(index);
            actions.listen?.(record.text);
          });
          listen.title = "Listen: " + record.text;
          listen.ariaLabel = listen.title;
          listen.innerHTML = icon("speaker");
          row.append(listen);
        } else row.append(el(doc, "span"));
        row.addEventListener("mouseenter", () => select(index));
        return row;
      }),
    );
    if (list.length === 0) bookList.append(el(doc, "li", "dh-book__empty", "No words typed this stage."));
    retryButton.innerHTML = icon("retry", { box: 25 }) + `<span class="dh-key">${keyLabel("enter")}</span>` + (s.outcome === "victory" ? "Replay" : "Retry");
    const easier = s.outcome === "defeat" ? (actions.easierOffer?.() ?? null) : null;
    offerEasier = easier !== null;
    setShown(easierButton, offerEasier);
    if (easier !== null) easierButton.innerHTML = `<span class="dh-key">${keyLabel("call-early")}</span>Lost twice: retry on ${easier}`;
    keys.innerHTML =
      (resultButtons.length > 1 ? `<span class="dh-key">${keyLabel("rotate-left")}</span><span class="dh-key">${keyLabel("rotate-right")}</span> buttons · ` : "") +
      `<span class="dh-key">${keyLabel("tilt-up")}</span><span class="dh-key">${keyLabel("tilt-down")}</span> words` +
      (actions.listen ? ` · <span class="dh-key">${keyLabel("replay")}</span> listen` : "");
    focusAction(0);
    setShown(screen, true);
    select(0);
  };

  const hide = (): void => {
    summary = null;
    pending = null;
    setShown(cheer, false);
    setShown(screen, false);
  };

  const showPending = (): void => {
    if (!pending) return;
    const { stars: count, wave } = pending;
    pending = null;
    setShown(cheer, false);
    show("victory", count, wave);
  };

  const onEvents = (events: readonly SimEvent[], w: World): void => {
    if (w !== world) {
      // A new run: start a fresh log.
      log.reset();
      hurt = emptyHurt();
      hide();
    }
    world = w;
    log.onEvents(events);
    tallyHurt(hurt, events);
    for (const event of events) {
      if (event.type === "victory") {
        pending = { stars: event.stars, wave: w.wave, at: -1 };
        setShown(cheer, true);
      } else if (event.type === "defeat") show("defeat", 0, event.wave);
    }
  };

  const frame = (w: World, info: FrameInfo): void => {
    if (w !== world) {
      log.reset();
      hurt = emptyHurt();
      hide();
      world = w;
    }
    if (pending) {
      if (pending.at < 0) pending.at = info.now + VICTORY_HOLD_MS;
      else if (info.now >= pending.at) showPending();
    }
  };

  const handleAction = (action: string): boolean => {
    if (pending) {
      // The hold takes every key; Enter or Esc skips to the panel.
      if (action === "enter" || action === "escape") showPending();
      return true;
    }
    if (!summary) return false;
    if (action === "enter") resultButtons[focusedAction]!.click();
    else if (action === "rotate-left" || action === "rotate-right") focusAction((focusedAction + 1) % resultButtons.length);
    else if (action === "call-early" && offerEasier) actions.easier?.();
    else if (action === "tilt-up") select(selected - 1);
    else if (action === "tilt-down") select(selected + 1);
    else if (action === "replay") {
      const record = list[selected];
      if (record) actions.listen?.(record.text);
    }
    // Everything else waits while the screen is up.
    return true;
  };

  return {
    onEvents,
    frame,
    handleAction,
    dispose(): void {
      screen.remove();
      cheer.remove();
    },
  };
}

src/ui/skin.ts:
/**
 * The carved-wood UI skin (DESIGN.md §1, 05 §4): Cormorant Garamond titles,
 * Be Vietnam Pro battle text, kit/ui semantic colours and --ui scale, and
 * src/ui/styles/dh.css. Installs once at boot. Also the small DOM helpers and
 * authored icons every UI part shares. Buttons never take focus (06 §2 rule 7).
 * Owner: ui (LANES.md).
 */
import "@fontsource/be-vietnam-pro/400.css";
import "@fontsource/be-vietnam-pro/700.css";
import "@fontsource/be-vietnam-pro/800.css";
import "@fontsource/cormorant-garamond/700.css";
// IPA lines (05 §4.4): Be Vietnam Pro lacks most IPA glyphs; kit IPA_FONT_FAMILY lists Noto Sans first.
import "@fontsource/noto-sans/latin-400.css";
import "@fontsource/noto-sans/latin-ext-400.css";
import "@fontsource/noto-sans/greek-400.css";
import "./styles/dh.css";
import { applyUiScale, installKitStyles } from "../kit/ui";
import { KEYS } from "../content/rules";
import type { Family } from "../content/types";
import art from "./ui-art.json";

const SKIN_FLAG = "dhSkin";

/** Installs fonts, kit tokens and the game stylesheet on `doc`; keeps --ui in step with the viewport. */
export function installSkin(doc: Document): void {
  const root = doc.documentElement;
  root.classList.add("dh-skin");
  if (root.dataset[SKIN_FLAG] === "1") return;
  root.dataset[SKIN_FLAG] = "1";
  const warned = new Set<string>();
  doc.addEventListener("error", (event) => handleArtError(event, warned), true);
  installKitStyles(doc as unknown as Parameters<typeof installKitStyles>[0]);
  const view = doc.defaultView;
  if (!view) return;
  const rescale = (): void => {
    applyUiScale(view.innerWidth, view.innerHeight, doc as unknown as Parameters<typeof applyUiScale>[2]);
  };
  rescale();
  view.addEventListener("resize", rescale);
}

// ── DOM helpers ─────────────────────────────────────────────────────────────

/** A new element with a class and optional text. */
export function el<K extends keyof HTMLElementTagNameMap>(doc: Document, tag: K, className = "", text?: string): HTMLElementTagNameMap[K] {
  const node = doc.createElement(tag);
  if (className) node.className = className;
  if (text !== undefined) node.textContent = text;
  return node;
}

/** A button that never takes focus from the window key router: tabindex −1, mousedown default blocked. */
export function uiButton(doc: Document, className: string, onPress: (event: MouseEvent) => void): HTMLButtonElement {
  const button = el(doc, "button", "dh-btn " + className);
  button.type = "button";
  button.tabIndex = -1;
  button.addEventListener("mousedown", (event) => event.preventDefault());
  button.addEventListener("click", (event) => {
    event.preventDefault();
    event.stopPropagation();
    if (!button.disabled) onPress(event);
  });
  return button;
}

/** Sets text only when it changed (HUD parts update every frame). */
export function setText(node: Node, text: string): void {
  if (node.textContent !== text) node.textContent = text;
}

/** Toggles a class only when it changed. */
export function setClass(node: Element, name: string, on: boolean): void {
  if (node.classList.contains(name) !== on) node.classList.toggle(name, on);
}

/** Sets a CSS custom property only when it changed. */
export function setVar(node: HTMLElement, name: string, value: string): void {
  if (node.style.getPropertyValue(name) !== value) node.style.setProperty(name, value);
}

/** Shows or hides a node by the `hidden` attribute. */
export function setShown(node: HTMLElement, shown: boolean): void {
  if (node.hidden === shown) node.hidden = !shown;
}

/** A number with at most one decimal, US style ("1.5"). */
export function viNumber(value: number): string {
  const rounded = Math.round(value * 10) / 10;
  return String(rounded);
}

// ── Key labels (00 §6: event.code; Alt is Option on Mac, Shift on Linux for digits) ──

export type KeyPlatform = "mac" | "linux" | "other";

export function keyPlatform(nav: { readonly platform?: string; readonly userAgent?: string } | undefined = globalThis.navigator): KeyPlatform {
  const text = ((nav?.platform ?? "") + " " + (nav?.userAgent ?? "")).toLowerCase();
  if (text.includes("mac")) return "mac";
  if (text.includes("linux") && !text.includes("android")) return "linux";
  return "other";
}

const CODE_LABEL: Readonly<Record<string, string>> = {
  Enter: "↵",
  Escape: "Esc",
  Backspace: "⌫",
  Tab: "Tab",
  Backquote: "`",
  Equal: "=",
  Minus: "-",
  ArrowLeft: "←",
  ArrowRight: "→",
  ArrowUp: "↑",
  ArrowDown: "↓",
};

/** The keycap text of a key-table action: "⌥1" on Mac, "Alt+1" elsewhere, "Shift+1" for digits on Linux. */
export function keyLabel(action: string, platform: KeyPlatform = keyPlatform()): string {
  const binding = KEYS.find((key) => key.action === action);
  if (!binding) return "";
  const base = binding.code.startsWith("Digit") ? binding.code.slice(5) : CODE_LABEL[binding.code] ?? binding.code;
  if (binding.mod === "none") return base === "↵" && platform !== "mac" ? "Enter" : base;
  const digit = binding.code.startsWith("Digit");
  const mod = binding.mod === "alt" && digit && platform === "linux" ? "shift" : binding.mod;
  if (platform === "mac") return (mod === "alt" ? "⌥" : "⇧") + base;
  return (mod === "alt" ? "Alt+" : "Shift+") + (base === "↵" ? "Enter" : base);
}

// ── Authored UI icons; three SVGs still await accepted art. ───────────

const svg = (body: string): string =>
  `<svg viewBox="0 0 24 24" aria-hidden="true" focusable="false">${body}</svg>`;

const STILL_SVG: Readonly<Record<string, string>> = {
  armour: svg('<path d="M12 2.8 4.5 5.6v6.1c0 4.6 3.1 8 7.5 9.5 4.4-1.5 7.5-4.9 7.5-9.5V5.6z" fill="#8f9aa3" stroke="#2a2420" stroke-width="1.2"/><path d="M12 5.6v13" stroke="#cfd6dc" stroke-width="1.4"/>'),
  dragon: svg('<path d="M4 17c2-1 3-3.5 3-6.5C7 6.5 9.6 4 13 4c2.5 0 4.6 1.4 5.6 3.6L21 8.4l-2 1.6c0 3.6-2.6 6.5-6.2 7l-1.8 3-1.6-2.4L6.5 21z" fill="#e8875a" stroke="#5a1c0c" stroke-width="1.1" stroke-linejoin="round"/><circle cx="15.2" cy="8" r="1.1" fill="#fff1c8"/><path d="M9 9.5c1.5-.6 2.6-.4 3.6.6" stroke="#ffd0a0" stroke-width="1.1" fill="none"/>'),
  "white-dragon": svg('<path d="M4 17c2-1 3-3.5 3-6.5C7 6.5 9.6 4 13 4c2.5 0 4.6 1.4 5.6 3.6L21 8.4l-2 1.6c0 3.6-2.6 6.5-6.2 7l-1.8 3-1.6-2.4L6.5 21z" fill="#eef1f2" stroke="#5a6470" stroke-width="1.1" stroke-linejoin="round"/><circle cx="15.2" cy="8" r="1.1" fill="#5a8ab8"/>'),
};

export interface IconOptions {
  readonly box?: number;
  readonly label?: boolean;
}

const ART_BY_KEY = new Map(art.icons.flatMap((entry) => [entry.name, ...entry.keys].map((key) => [key, entry] as const)));
const escapeAttribute = (text: string): string => text.replace(/[&"<>]/g, (ch) => ({ "&": "&amp;", '"': "&quot;", "<": "&lt;", ">": "&gt;" })[ch]!);

/** Markup uses the table alone; later art replacements need no caller changes. */
export function icon(name: string, { box = 20, label = false }: IconOptions = {}): string {
  const entry = ART_BY_KEY.get(name);
  if (!entry) return STILL_SVG[name] ?? "";
  const size = entry.sizes.find((candidate) => candidate >= box * 2.4) ?? entry.sizes[entry.sizes.length - 1]!;
  return `<img class="dh-art" src="/assets/dragon-hold/ui/icons/${entry.name}.${size}.webp?v=${art.version}" width="${box}" height="${box}" alt="${label ? escapeAttribute(entry.alt) : ""}"${label ? "" : ' aria-hidden="true"'} decoding="async" draggable="false" style="--dh-art-box:${box}px">`;
}

/** Kept for callers that read the shared table directly. */
export const ICONS: Readonly<Record<string, string>> = Object.fromEntries([
  ...Object.keys(STILL_SVG).map((name) => [name, icon(name)]),
  ...[...ART_BY_KEY.keys()].map((name) => [name, icon(name)]),
]);
export type IconName = keyof typeof ICONS;

/** Family portraits replace the former gait silhouettes. */
export function foeIcon(family: Family, options?: IconOptions): string {
  return icon("family-" + family, options);
}

interface ArtErrorTarget {
  readonly tagName: string;
  readonly classList?: { contains(name: string): boolean };
  readonly currentSrc?: string;
  readonly src?: string;
  hidden: boolean;
}

/** Capture errors without a DOM dependency; each document warns once per URL. */
export function handleArtError(event: { readonly target: unknown }, warned: Set<string>, warn: (message: string) => void = console.warn): void {
  const image = event.target as ArtErrorTarget | null;
  if (image?.tagName !== "IMG" || !image.classList?.contains("dh-art")) return;
  const url = image.currentSrc || image.src || "";
  if (!warned.has(url)) {
    warned.add(url);
    warn("[ui-art] missing image: " + url);
  }
  image.hidden = true;
}

